        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u5728\u6e38\u620f\u8fd0\u884c\u81ea\u5df1\u7684\u5e27\u65f6\u7ed8\u5236\u7b2c\u4e00\u4eba\u79f0\u89c6\u56fe\uff1a\u66f4\u591a\u5e27\uff0c\u56fe\u7247\u968f\u9f20\u6807\u79fb\u52a8\uff0c\u4ee5\u4fbf\u4fdd\u6301\u4e00\u81f4\uff1b 0 \u6b65\u957f\u7ed8\u5236", "# draw the first-person view while the game runs its own frame: more frames, the picture moved with your mouse so it keeps up; 0 draws it in step"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5728 {1:F1}\u3001{2:F1} \u5904 ping {0}\uff08{3:F0} \u74f7\u7816{4}\uff09{5}{6}", "ping {0} at {1:F1},{2:F1} ({3:F0} tiles{4}){5}{6}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fdb\u5165{0}\uff1a{1}\u5c42{2}{3}\uff0c{4}x{5}\u623f\u95f4\uff0c{6}\u6a21\u578b\uff0c{7}\u706f\uff0c{8}\u91cc\u9762\u7684\u4eba", "entered {0}: {1} tier {2}{3}, {4}x{5} room, {6} models, {7} lights, {8} people inside"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u88ab\u6d3e\u53bb\u5728\u6218\u4e89\u5730\u56fe\u4e0a\u6807\u8bb0 {warFlag.Number}\u3002\u7ad9\u5728\u90a3\u91cc\u5e76\u4e0e\u4efb\u4f55\u53d1\u751f\u7684\u4e8b\u60c5\u6218\u6597", "You were sent to flag {warFlag.Number} on the war map. Stand there and fight whatever comes"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u53ea\u6709\u56fd\u738b\u624d\u4f1a\u4fdd\u7559\u6218\u4e89\u5730\u56fe\u3002\u4f5c\u4e3a\u58eb\u5175\u6216\u521b\u59cb\u4eba\u5165\u4f0d\uff08\u8be2\u95ee\u60a8\u57ce\u9547\u7684\u9886\u5bfc\uff09\uff0c\u60a8\u7684\u547d\u4ee4\u5c06\u663e\u793a\u5728\u6b64\u5904\u3002", "Only kings keep a war map. Enlist as a soldier or a founder (ask your town's leader) and your orders will show here."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd8\u6ca1\u6709\u4efb\u52a1\u3002\u95ee\u4eba\u4eec\u201c\u6709\u9002\u5408\u6211\u7684\u5de5\u4f5c\u5417\uff1f\u201d\u5f53\u4f60\u4e0e\u4ed6\u4eec\u4ea4\u8c08\u6216\u9605\u8bfb\u57ce\u9547\u7684\u8d4f\u91d1\u677f\u65f6\u3002\u4f60\u53ef\u4ee5\u643a\u5e26 ", "No tasks yet. Ask people \"Any work for me?\" when you talk to them, or read a town's bounty board. You can carry "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u544a\u8bc9\u4ed6\u4eec\u4f60\u77e5\u9053\u3002\u6709\u7684\u8fd8\u94b1\u3002\u6709\u4e9b\u4eba\u4f1a\u62ff\u5200\uff0c\u6240\u4ee5\u8981\u505a\u597d\u51c6\u5907\u3002\u4e0d\u7ba1\u600e\u6837\uff0c\u8bf7\u8fc7\u6765\u544a\u8bc9\u6211\u90a3\u4eba\u662f\u8c01\u3002", "Tell them you know. Some give the money back. Some go for their knife, so be ready. Either way, come and tell me who it was."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u751f\u7269\uff08\u4eba\u3001\u52a8\u7269\u3001\u602a\u7269\uff09\u4ee5 3D \u5f62\u5f0f\u505c\u7559\u5728\u6b64\u5904\uff0c\u4ee5\u56fe\u5757\u5f62\u5f0f\u663e\u793a\uff0c\u4e5f\u8d85\u51fa\u4e86\u7ec6\u8282\u8ddd\u79bb\uff1b ", "# creatures (people, animals, monsters) stay 3D out to here, in tiles, also past the detail distance; "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u5728\u7b2c\u4e00\u4eba\u79f0\u4e2d\uff0c\u4f60\u9644\u8fd1\u7684\u751f\u7269\u6309\u7167\u4ed6\u4eec\u7684\u6b65\u8c03\u884c\u8d70\uff08\u6218\u6597\u548c\u9003\u8dd1\u4fdd\u6301\u5168\u901f\uff1b\u4e16\u754c\u65f6\u949f\u672a\u53d7\u5f71\u54cd\uff09", "# in first person, the creatures near you walk at this share of their pace (fights and fleeing stay full speed; the world's clock is untouched)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u767d\u5929\u7684\u9e1f\u9e23\u58f0\uff0c\u665a\u4e0a\u7684\u87cb\u87c0\u3001\u732b\u5934\u9e70\u548c\u9752\u86d9\u7684\u9e23\u53eb\u58f0\uff1a0 \u9759\u97f3\uff0c1 \u6b63\u5e38\uff08\u67d4\u548c\uff09\uff0c2 \u5927\u58f0", "# birdsong by day, crickets, owls and frogs by night: 0 silent, 1 normal (soft), 2 louder"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u9ec4\u91d1\u6d88\u606f\u4f20\u5230\u4e86{Royal.NameOf(target)}\uff1a{num}\u9ec4\u91d1\u5728\u4f60\u5934\u4e0a", "Word of your gold reached {Royal.NameOf(target)}: {num} gold on your head there"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("   \uff08{((Vector2)(ref val)).magnitude:F0} \u74f7\u7816\uff09", "   ({((Vector2)(ref val)).magnitude:F0} tiles)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u9547\u653f\u5e9c\u4e3a {1} \u652f\u4ed8 {0} \u9ec4\u91d1\u3002\u6740\u6b7b\u5b83\uff0c\u7136\u540e\u5728\u68cb\u76d8\u4e0a\u6216\u4ece\u9547\u4e0a\u7684\u9886\u5bfc\u90a3\u91cc\u9886\u53d6\u5956\u52b1\u3002", "The town's board pays {q.Money} gold for the {q.TargetName}. Kill it, then claim the reward at the board or from a leader of the town."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# 3D\u5730\u56fe\u663e\u793a\u591a\u8fdc\uff08\u5730\u56fe\u76f8\u673a\u7684\u53d8\u7126\uff09\uff1b\u518d\u8fdc\u4e00\u70b9\uff0c\u5b83\u5c31\u4f1a\u6d88\u5931\u5728\u5e73\u9762\u5730\u56fe\u4e0a\u3002\u6846\u67b6\u6210\u672c\u8f83\u9ad8", "# how far out the 3D map shows (the map camera's zoom); further out it fades to the flat map. Higher costs frames"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5b8c\u6210 {Quests.Completed} \u00b7 \u5931\u8d25 {Quests.Failed}", "Done {Quests.Completed}  \u00b7  failed {Quests.Failed}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u7b2c\u4e00\u4eba\u79f0\u97f3\u4e50\uff08\u65f6\u4e0d\u65f6\u5e73\u9759\u7684\u97f3\u4e50\uff0c\u6218\u6597\u4e2d\u7684\u6218\u6597\u97f3\u4e50\uff09\uff1a0 \u5173\u95ed\uff0c1 \u6b63\u5e38\uff0c2 \u5927\u58f0", "# first-person music (calm pieces now and then, battle music in a fight): 0 off, 1 normal, 2 louder"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u7b2c\u4e00\u4eba\u79f0\u53f3\u4e0a\u89d2\u7684\u5c0f\u5730\u56fe\uff08N \u663e\u793a\u6216\u9690\u85cf\u5b83\uff1b\u6309\u4f4f N \u53ef\u4ee5\u67e5\u770b\u4f60\u63a2\u7d22\u8fc7\u7684\u6574\u4e2a\u5730\u56fe\uff09", "# the minimap top right in first person (N shows or hides it; hold N for the whole map you've explored)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u9700\u8981\u660e\u786e\u7684\u662f\uff1a{0} \u901a\u8fc7\u4f60\u7684\u8bb2\u9053\uff0c{2} \u66f4\u591a\u7684\u4eba\u8f6c\u5411\u4e86 {1}\u3002\u4e3a\u6b64\uff0c{3}\u3002", "To be clear: {q.Need} more people turned to {q.Thing} by your preaching, {text}. For that, {text2}."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd9\u91cc\uff1a{q.Need} {Work.ResourceName(q.Thing)}\u3002", "Here: {q.Need} {Work.ResourceName(q.Thing)}."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# 0 \u767d\u5929\u548c\u9ed1\u591c, 1 \u603b\u662f\u767d\u5929, 2 \u9ec4\u91d1\u65f6\u6bb5, 3 \u603b\u662f\u591c\u665a (\u6e38\u620f\u4e2dF7)", "# 0 day and night, 1 always day, 2 golden hour, 3 always night (F7 in game)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# mod \u81ea\u5e26\u7684\u97f3\u6548\uff08\u6447\u6446\u3001\u649e\u51fb\u3001\u5f13\u3001\u811a\u6b65\u3001\u98ce\u96e8\uff09\uff1a0 \u5173\u95ed\uff0c1 \u6b63\u5e38\uff0c2 \u5927\u58f0", "# the mod's own sound effects (swings, hits, the bow, steps, wind and rain): 0 off, 1 normal, 2 louder"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("{((NanoObject)city).name}\u611f\u6069\uff08+{favour}\u5fe0\u8bda\uff09", "{((NanoObject)city).name} is grateful (+{favour} loyalty)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u53f3\u952e\u5355\u51fb\u6982\u8ff0\u7684\u571f\u5730\u5c06\u5176\u8bbe\u4e3a\u60a8\u7684\u7ad9\u70b9\u3002\u62d6\u52a8\u6216\u6309 WASD \u8fdb\u884c\u79fb\u52a8\uff0c\u6eda\u8f6e\u8fdb\u884c\u7f29\u653e\u3002", "Right-click outlined land to make it your site. Drag or WASD to move, the wheel to zoom."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6240\u6709\u516d\u4e2a\u6807\u5fd7\u5747\u5df2\u5347\u8d77\u3002\u5c06\u5176\u4e2d\u4e00\u4e2a\u62d6\u52a8\u5230\u6b64\u5904\uff0c\u6216\u8005\u53f3\u952e\u5355\u51fb\u6ca1\u6709\u6807\u8bb0\u7684\u4e00\u4e2a\u5c06\u5176\u62c9\u51fa\u3002", "All six banners are raised. Drag one here, or right-click an unmarked one to pull it out."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u5c4f\u5e55\u4e0a\u7684\u6447\u6746\u548c\u6309\u94ae: 0 \u81ea\u52a8\uff08\u5728\u624b\u673a\u4e0a\uff0c\u6216\u89e6\u6478\u5c4f\u5e55\u540e\uff09\uff0c1 \u59cb\u7ec8\uff0c2 \u4ece\u4e0d", "# on-screen stick and buttons: 0 auto (on a phone, or once you touch the screen), 1 always, 2 never"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("{((NanoObject)city).name}\u73b0\u5728\u53ea\u80fd\u652f\u4ed8{num}\u91d1\u5e01\u3002", "{((NanoObject)city).name} can only pay {num} gold now."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u53f3\u952e\uff1a\u6218\u58eb\u65d7\u5e1c\uff1b\u8239\u53ea\u9a76\u5165\u6c34\u4e2d\u6216\u5411\u654c\u4eba\u5f00\u706b\uff08Ctrl\uff1a\u70b9\uff09\u3002\u62d6\u52a8\u65d7\u5e1c\u6765\u79fb\u52a8\u5176\u5e26\u3002", "Right-click: warrior banners; ships sail into water or fire at enemies (Ctrl: strike). Drag a banner to move its band."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u90a3\u5c31\u6218\u6597\u5427\u3002\u6211\u4f1a\u7d27\u8ddf\u5728\u4f60\u8eab\u540e\u3002\u5982\u679c\u6211\u6b7b\u4e86\uff0c\u4e00\u5207\u5c31\u90fd\u7ed3\u675f\u4e86\uff0c\u6240\u4ee5\u8bf7\u8fdc\u79bb\u6211\u548c\u9ebb\u70e6\u3002", "Then fight. I'll stay close behind you. If I die, it's over, so keep between me and the trouble."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u4e8b\u7269\u4ee5\u56fe\u5757\u5f62\u5f0f\u5b8c\u6574\uff083D\uff09\u7ed8\u5236\u5230\u6b64\u5904\uff1b\u66f4\u8fdc\u7684\u751f\u7269\u662f\u8272\u5f69\u7684\u6591\u70b9\uff0c\u53ea\u6709\u9646\u5730\u663e\u793a", "# things are drawn whole (3D) out to here, in tiles; further off creatures are specks of colour and only the land shows"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5355\u51fb\uff0c\u6216\u63091-{heirs.Count}\u00b7\u6216\u7b49\u5f85\uff08{num12:F0}\uff09\u677e\u624b", "Click, or press 1-{heirs.Count}   \u00b7   or wait ({num12:F0}) to let go"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u5305\u91cc\u6ca1\u6709\u4ed6\u4eec\u80fd\u5403\u7684\u4e1c\u897f\u3002\u91c7\u6458\u6d46\u679c\u6216\u72e9\u730e\uff08\u5728\u704c\u6728\u4e1b\u6216\u6e38\u620f\u4e2d\u6309\u4f4f\u9f20\u6807\u5de6\u952e\uff09\u3002", "Nothing in your bag they can eat. Pick berries or hunt (hold the left mouse button on bushes, or on game)."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8d70\u5230\u65d7\u5e1c\u5904\uff0c\u6216\u8d70\u5230\u4efb\u4f55\u6807\u5b9a\u7684\u7a7a\u5730\u4e0a\u3002\u7ad9\u5728\u4e0a\u9762\u6309E\u952e\u6765\u63d0\u5347\u6751\u5e84\u3002\u4f60\u4f1a\u9886\u5bfc\u5b83\u3002", "Walk to the flag, or onto any outlined free land. Stand on it and press E to raise the village. You'll lead it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u7b2c\u4e00\u4eba\u79f0\u6a21\u7ec4\u8bbe\u7f6e\uff1a\u6e38\u620f\u4e2d\u7684 F2 \u66f4\u6539\u5b83\u4eec\uff08\u4ec5\u5728\u6e38\u620f\u5173\u95ed\u65f6\u7f16\u8f91\u6b64\u6587\u4ef6\uff09", "# First Person mod settings: F2 in the game changes them (edit this file only while the game is closed)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u4f60\u5728\u7b2c\u4e00\u4eba\u79f0\u4e2d\u542c\u5230\u7684\u4e00\u5207\uff0c\u6e38\u620f\u672c\u8eab\u7684\u58f0\u97f3\u4e5f\u662f\uff1a0 \u65e0\u58f0 .. 1 \u5168\u58f0", "# everything you hear in first person, the game's own sounds too: 0 silent .. 1 full"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7b2c\u4e00\u4eba\u79f0\u5934\u4e0a\u7684 # \u6807\u8bb0\uff1a0 \u65e0\u30011 \u654c\u4eba\uff08\u7ea2\u8272\uff09\u30012 \u654c\u4eba\u548c\u670b\u53cb\uff08\u84dd\u8272\uff09", "# marks over heads in first person: 0 none, 1 foes (red), 2 foes and friends (blue)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff0c{familyTree.PastChiefs} \u914b\u957f\u4eec\u4ece\u6b64\u5f00\u59cb\u9886\u5bfc\u5b83\u3002", ", and {familyTree.PastChiefs} chiefs have led it since."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u4e0d\u5c5e\u4e8e\u4efb\u4f55\u738b\u56fd\u3002\u52a0\u5165\u4e00\u4e2a\u57ce\u9547\uff08\u4e0e\u5b83\u7684\u9886\u5bfc\u8005\u4ea4\u8c08\uff09\uff0c\u5b83\u7684\u65b0\u95fb\u5c06\u7531\u4f60\u638c\u63e1\u3002", "You belong to no realm. Join a town (talk to its leader) and its news will be yours."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd8\u6ca1\u6709\u5173\u4e8e\u4f60\u7684\u738b\u56fd\u7684\u6d88\u606f\u3002\u5982\u679c\u4f60\u7684\u57ce\u5e02\u906d\u5230\u653b\u51fb\u6216\u5360\u9886\uff0c\u4f60\u4f1a\u7acb\u5373\u542c\u5230\u6d88\u606f\u3002", "No news of your realm yet. Should a city of yours be attacked or taken, you'll hear of it at once."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5df2\u7ecf\u8bf4\u8fc7\u4e86 \u5c31\u8fd9\u6837\u7ed3\u675f\u4e86\u5982\u679c\u4ed6\u4eec\u53ea\u662f\u8bf4\u4e0d\u2026\u2026\u5fc3\u5c31\u4f1a\u6539\u53d8\u3002\u6539\u5929\u518d\u8bd5\u4e00\u6b21\u3002", " is already spoken for, that's the end of it. If they just say no... hearts change. Try again another day."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u5c06\u5728 {1} \u5185\u8fbe\u5230 {0}\u3002\u7136\u540e\u662f {2}\uff0c\u4f60\u5c06\u83b7\u5f97 {3} \u91d1\u5e01\u3002", "You'll {Goal(q)}, within {Span(MonthsFor(q))}. Then {Then(q)}, and you'll have {q.Money} gold for it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u6444\u50cf\u673a\u4ece\u5730\u56fe\u8fdb\u5165\u751f\u7269\u7684\u773c\u775b\u5e76\u8fd4\u56de\uff1a1 \u6b63\u5e38\uff0c2 \u4e24\u500d\u5feb\uff0c0 \u76f4\u7ebf\u526a\u5207", "# the camera's dive from the map into the creature's eyes and back: 1 normal, 2 twice as fast, 0 a straight cut"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8d2d\u4e70{((NanoObject)k).name}\u7684{num2}\u5e74\u7684\u4fdd\u62a4", "Buy {((NanoObject)k).name}'s protection for {num2} years"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u8fd8\u6ca1\u6709\u5bb6\u4eba\u3002\u627e\u4e2a\u60c5\u4eba\uff08\u8bf4\u8bdd\uff0c\u7136\u540e\u7528 R \u8c03\u60c5\uff09\uff1b\u4f60\u7684\u5b69\u5b50\u4e5f\u4f1a\u5728\u8fd9\u91cc\u3002", "You have no family yet. Find a lover (talk, then R to flirt); your children will be here too."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u53ea\u662f...\u544a\u8bc9\u4ed6\u4eec\u6211\u5f88\u559c\u6b22\u4ed6\u4eec\u3002\u8f7b\u8f7b\u5730\u3002\u5e76\u51c6\u786e\u5730\u544a\u8bc9\u6211\u4ed6\u4eec\u56de\u590d\u4e86\u4ec0\u4e48\u3002", "Just... tell them I'm sweet on them. Gently. And tell me exactly what they say back."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u56fd\u738b\u652f\u4ed8{arg} {got}\u9ec4\u91d1\uff0c\u5176\u6240\u6709\u91d1\u5e93\u90fd\u53ef\u4ee5\u817e\u51fa{owed}\u3002", "The crown pays{arg} {got} gold, all its coffers could spare of {owed}."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u5728 3D \u7ed8\u5236\u4e16\u754c\u65f6\u7b49\u5f85\u5c4f\u5e55\u5237\u65b0\uff1a\u8f6c\u52a8\u65f6\u4e0d\u4f1a\u6495\u88c2\uff1b 0\u53ef\u4ee5\u591a\u7ed9\u51e0\u5e27", "# wait for the screen's refresh while the world is drawn in 3D: no tearing when you turn; 0 can give a few more frames"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7ed9 {count} {Work.ResourceName(res)}", "Give {count} {Work.ResourceName(res)}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("#\u4f60\u7684\u6253\u51fb\u548c\u5c04\u51fb\u4e5f\u4f24\u5bb3\u4e86\u4f60\u81ea\u5df1\u7684\u4e00\u65b9\uff080\uff1a\u5b83\u4eec\u8d8a\u8fc7\u4f60\u7684\u738b\u56fd\u53ca\u5176\u76df\u53cb\uff09", "# your blows and shots hurt your own side too (0: they pass over your kingdom and its allies)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5927\u7ea6 {Mathf.RoundToInt(months)} \u4e2a\u6708\u540e", "in about {Mathf.RoundToInt(months)} months"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u591c\u665a\u8fc7\u53bb\u4e86*\u7a0d\u540e\uff0c\u4e00\u58f0\u8f7b\u67d4\u7684\u8033\u8bed\uff1a\u201c\u6211\u60f3\u2026\u2026\u6211\u4eec\u8981\u751f\u4e2a\u5b69\u5b50\u4e86\u3002\u201d", "*the night passes* Later, a quiet whisper: \"I think... we're going to have a baby.\""));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u795e\u89c6\u56fe\uff1a\u753b\u5e03{0} {1}\u56fe\u5c42{2}\u8ba2\u5355{3}\u76f8\u673a{4}\u4e3b\u52a8{5}", "god view: canvas {0} {1} layer {2} order {3} camera {4} active {5}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8d2d\u4e70 {5} {Work.ResourceName(text)}", "Buy {5} {Work.ResourceName(text)}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u8fd8\u6ca1\u6709\u5bb6\u4eba\u8ddf\u968f\u4f60\u3002\u4e00\u65e6\u4f60\u62e5\u6709\u4e86\u4f60\u7684\u7231\u4eba\u6216\u5b69\u5b50\uff0c\u4ed6\u4eec\u5c31\u4f1a\u8fd9\u4e48\u505a\u3002", "You have no family to follow you yet. A lover or children of yours will, once you have them."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u63a5\u7ba1\u4e00\u4e2a\u751f\u7269\uff08\u6f5c\u5165\u5730\u56fe\u4e2d\u7684\u4e00\u4e2a\u751f\u7269\uff09\u5e76\u4e3a\u5176\u8d4b\u4e88\u6b66\u5668\u3001\u76d4\u7532\u548c\u7279\u6027\u3002", "Take over a creature (dive into one from the map) to give it weapons, armor and traits here."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6bcf\u4e2a\u57ce\u9547\u4e00\u6b21\u4e00\u4efd\u8d4f\u91d1\u3002\u6740\u6b7b\u76ee\u6807\uff0c\u7136\u540e\u5728\u8fd9\u91cc\u6216\u4ece\u9886\u5bfc\u8005\u90a3\u91cc\u9886\u53d6\u5b83\u3002", "One bounty at a time per town. Kill the target, then claim it here or from a leader."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6309 I \u770b\u770b\u4f60\u53ef\u4ee5\u5236\u4f5c\u4ec0\u4e48\uff0c\u4ee5\u53ca\u5b83\u9700\u8981\u4ec0\u4e48\u3002\u643a\u5e26\u65f6\u5c06\u5176\u63e1\u5728\u624b\u4e2d\u3002", "Press I to see what you can craft, and what it needs. Hold it in your hand when you bring it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f20\u6559{q.Thing}\uff1a{q.Have}/{q.Need}\u5df2\u8f6c\u6362", "Preach {q.Thing}: {q.Have}/{q.Need} converted"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u62d6\u52a8\u5728\u89e6\u6478\u5c4f\u4e0a\u8f6c\u52a8\u89c6\u56fe\u7684\u901f\u5ea6\u6709\u591a\u5feb: 1 = \u5c4f\u5e55\u9ad8\u5ea6\u662f\u534a\u5708", "# how fast a drag turns the view on a touchscreen: 1 = the screen's height is half a turn"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u738b\u56fd\u906d\u88ad\u6216\u5931\u53bb\u57ce\u5e02\u65f6\u663e\u793a\u901a\u77e5\uff1b\u5168\u90e8\uff1a\u540c\u65f6\u5728\u5de6\u4fa7\u663e\u793a\u4e16\u754c\u65b0\u95fb\uff08U\uff09", "A banner when your realm is attacked or loses a city; All adds the world's news at the left (U)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u6ca1\u6709\u5bb6\u4eba\u966a\u4f60\u53bb\uff0c\u6240\u4ee5\u4f60\u4e00\u4e2a\u4eba\u53bb\uff1b\u4e00\u65e6\u5b83\u7ad9\u8d77\u6765\uff0c\u5176\u4ed6\u4eba\u5c31\u4f1a\u6765\u3002", "You've no family here to go with you, so you'll go alone; others will come once it stands."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\n\u4f60\u7684\u5730\u56fe\uff08M\uff09\u6307\u660e\u4e86\u9053\u8def\uff1b\u5982\u679c\u4f60\u627e\u5230\u66f4\u597d\u7684\uff0c\u4efb\u4f55\u7a7a\u5730\u90fd\u53ef\u4ee5\u3002", "\nYour map (M) shows the way; any free land will do if you find better."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u751f\u6d3b\u5728{list.Count}\u7edf\u6cbb\u8005\u7684\u7edf\u6cbb\u4e4b\u4e0b\uff1a{arg}\u3002", "I've lived under {list.Count} rulers: {arg}."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6ca1\u6709\u4fe1\u4ef0\u7684\u4eba\u6700\u597d\u542c\u3002\u90a3\u4e9b\u62e5\u6709\u53e6\u4e00\u79cd\u4fe1\u4ef0\u7684\u4eba\u5219\u52aa\u529b\u575a\u6301\u8fd9\u4e00\u4fe1\u4ef0\u3002", "Folk without faith listen best. Those of another faith hold to it hard."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u624b\u673a\u7684\u706f\u5149\u8bbe\u7f6e\u5df2\u8bbe\u7f6e\u8fc7\u4e00\u6b21 (0: \u4e0b\u6b21\u5728\u624b\u673a\u4e0a\u518d\u6b21\u8bbe\u7f6e)", "# the lighter settings for a phone were set once (0: set them again next time on a phone)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5730\u56fe\uff1a\u56fd\u738b\u67e5\u770b\u6218\u4e89\u5730\u56fe\uff0c\u58eb\u5175\u6216\u62d3\u8352\u8005\u67e5\u770b\u6307\u4ee4\uff0c\u5176\u4ed6\u89d2\u8272\u67e5\u770b\u5bb6\u5ead", "Map: a king's war map, a soldier's or founder's, else your family's"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u5728\u8fd9\u91cc\u627e\u4e0d\u5230\u6751\u5e84\uff1a\u5bfb\u627e\u8fdc\u79bb\u4efb\u4f55\u57ce\u9547\u7684\u7a7a\u5730\uff08\u800c\u4e0d\u662f\u5728\u6c34\u4e2d\uff09\u3002", "You can't found a village here: find open land away from any town (and not in the water)."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7a7a\u3002\u5728\u6811\u6728\u3001\u5ca9\u77f3\u3001\u77ff\u77f3\u3001\u704c\u6728\u548c\u519c\u4f5c\u7269\u4e0a\u6309\u4f4f\u9f20\u6807\u5de6\u952e\u8fdb\u884c\u91c7\u96c6\u3002", "Empty. Hold the left mouse button on trees, rocks, ore, bushes and crops to gather."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("W/S\u6216\u9f20\u6807\u9009\u62e9\u00b7E\uff0cEnter\u6216\u70b9\u51fb\u8bf4\u00b71-9\u00b7Esc\u79bb\u5f00", "W/S or mouse to choose   \u00b7   E, Enter or click to say   \u00b7   1-9   \u00b7   Esc to leave"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u90a3\u4f60\u8001\u5b9e\u544a\u8bc9\u6211\uff0c\u6211\u518d\u60f3\u529e\u6cd5\u3002\u5982\u679c\u4f60\u5c31\u8fd9\u4e48\u6d88\u5931\u4e86\uff0c\u6211\u4f1a\u5c11\u60f3\u4f60\u3002", "Then come and tell me honestly, and I'll find another way. I'd think less of you if you just vanished."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4f1a\u542c\u5230\u6bcf\u4e2a\u65b0\u7075\u9b42\u7684\u6d88\u606f\u3002\u6709{q.Need}\u7684\u65f6\u5019\u6765\u627e\u6211\u5427\u3002", "I'll hear of each new soul. When there are {q.Need}, come to me."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("{1} \u4e2d\u7684 {0}\uff01 {2} {3} \u9547\u5185\u3002\u628a\u4ed6\u4eec\u8d76\u51fa\u53bb\u3002", "{0} in {1}! {2} {3} inside the town. Drive them out."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ece{1}\u4e2d\u53d6\u51fa{0}\u3002 {2}\u5927\u519b\u884c\u8fdb\uff0c{3}\u5f3a\u5065\u3002 {4}", "Take {((NanoObject)target_attack_city).name} from {((NanoObject)target_attack_city.kingdom).name}. The army of {((NanoObject)city).name} marches, {order.Soldiers} strong. {text2}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u63a7\u4ef6\u4ec5\u5728\u7b2c\u4e00\u6b21\u663e\u793a\uff08F1 \u518d\u6b21\u663e\u793a\uff09\uff1b 0 \u518d\u6b21\u89c1\u5230\u4ed6\u4eec", "# the controls are shown the first time only (F1 shows them again); 0 to see them once more"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd8\u6ca1\u6709\u6d88\u606f\u3002\u56fd\u738b\u3001\u6218\u4e89\u3001\u57ce\u5e02\u548c\u707e\u96be\u7684\u53d1\u751f\u90fd\u4f1a\u5728\u8fd9\u91cc\u88ab\u8bb2\u8ff0\u3002", "No news yet. Kings, wars, cities and disasters will be told of here as they happen."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4efb\u52a1\u5b8c\u6210\uff1a{Title(q)} +{q.Money} \u91d1\u5e01", "Task done: {Title(q)}   +{q.Money} gold"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u66ff\u6211\u53bb\u90a3\u91cc\uff0c\u770b\u770b\u5723\u5730\uff0c\u7136\u540e\u544a\u8bc9\u6211\u3002\u6211\u592a\u8001\u4e86\uff0c\u4e0d\u9002\u5408\u4e0a\u8def\u4e86\u3002", "Go there for me, see the holy place, and tell me of it. I'm too old for the road."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u6ca1\u6709\u6218\u58eb\u3002\u4f60\u7684\u57ce\u5e02\u5728\u4ed6\u4eec\u6210\u957f\u7684\u8fc7\u7a0b\u4e2d\u8bad\u7ec3\u4ed6\u4eec\u5e76\u6b66\u88c5\u81ea\u5df1\u3002", "You have no warriors. Your cities train them as they grow and arm themselves."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65b9\u5c16\u7891\u5728\u4f60\u7684\u624b\u4e0b\u55e1\u55e1\u4f5c\u54cd\uff0c\u4f46\u4fdd\u6301\u6c89\u9ed8\u3002\u53ea\u6709\u56fd\u738b\u624d\u80fd\u5524\u9192\u5b83\u3002", "The obelisk hums under your hand, but stays silent. Only a king can wake it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u7ed8\u5236\u4e3a 3D \u4e16\u754c\u7684\u5730\u56fe\uff08\u5730\u56fe\u4e0a\u7684 V \u6253\u5f00\u548c\u5173\u95ed\u5b83\uff09", "# the map drawn as the 3D world (V on the map turns it on and off)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u4f60\u7684\u6218\u58eb\u9760\u8fd1\u4f60 ping \u7684\u654c\u4eba\uff08\u4e2d\u952e\u5355\u51fb\uff09\uff0c\u5168\u529b\u4ee5\u8d74", "# your warriors near an enemy you ping (middle click) go for it"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("GPU \u6e32\u67d3\u7684\u753b\u9762\u98ce\u683c\uff08\u5ba4\u5185\u548c\u4e09\u7ef4\u5730\u56fe\u4ecd\u7531 CPU \u6e32\u67d3\uff09", "How the graphics card paints the picture (rooms and the 3D map stay CPU)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff09\u3002\u5c06\u5176\u5b58\u653e\u5728\u60a8\u7684\u57ce\u5e02\uff08E \u5728\u4ed3\u5e93\uff09\u6216\u5236\u4f5c\u4e00\u4e9b\u4e1c\u897f\uff08I\uff09\u3002", "). Store it in your city (E at a storehouse) or craft something (I)."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u7cbe\u7075 {0} tex {1} \u53ef\u8bfb {2} \u77e9\u5f62 {3}", " sprite {0} tex {1} readable {2} rect {3}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u4f7f\u7528\u4e2d\uff1a\u89e6\u6478\u63a7\u4ef6\u9690\u85cf\uff08F2\uff0c\u89c6\u56fe\uff1a\u89e6\u6478\u63a7\u4ef6\u6253\u5f00\u4fdd\u6301\u5b83\u4eec\uff09", " In use: touch controls hidden (F2, View: touch controls on keeps them)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u591c\u665a\u8fc7\u53bb\u4e86* ...\u4f60\u611f\u89c9\u5230\u4e00\u4e9b\u65b0\u7684\u4e1c\u897f\u5728\u4f60\u4f53\u5185\u6405\u52a8\u3002", "*the night passes* ...You feel something new stirring inside you."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u5c06\u5728\u5047\u4eba\u8eab\u4e0a\u8fdb\u884c\u6f14\u4e60\uff0c\u4fdd\u8bc1\u57ce\u9547\u5b89\u5168\uff0c\u5e76\u5728\u4ec0\u4e48\u65f6\u5019\u884c\u519b ", "You'll drill at the dummy, keep the town safe, and march when "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("{0}\u62e5\u6709{1}\u5ea7\u57ce\u5e02\uff0c\u4eba\u53e3{3}\uff0c\u6709{4}\u540d\u6218\u58eb\u5f85\u547d\u3002", "{0} has {1} cit{2} and {3} souls. {4} warriors stand ready."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("#0 \u5e72\u51c0\u7684\u989c\u8272\uff0c1 \u4e2a\u6296\u52a8\u590d\u53e4\u8c03\u8272\u677f\uff08\u6e38\u620f\u4e2d\u7684 F8\uff09", "# 0 clean colors, 1 dithered retro palette (F8 in game)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("   \uff08\u6211\u8981\u67e5\u770b\u60a8\u6700\u559c\u6b22\u7684\u5185\u5bb9\uff0c[ ] \u5728\u5b83\u4eec\u4e4b\u95f4\u8df3\u8f6c\uff09", "   (I to see your favourites, [ ] to leap between them)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("Worldfall \u80cc\u666f\u97f3\u4e50\uff1a\u5173\uff08Ctrl+M \u6062\u590d\uff09", "Worldfall music: off (Ctrl+M to restore)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u597d\u3002\u6211\u4eec\u9700\u8981\u53cc\u624b\u3002\u519b\u961f\u4e2d\u7684\u957f\u77db\uff0c\u6216\u5efa\u7acb\u65b0\u6751\u5e84\u7684\u521b\u59cb\u4eba ", "Good. We need hands. A spear in the army, or a founder to raise a new village for "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(".\u4f60\u7684\u547d\u4ee4\u5c06\u663e\u793a\u5728\u4f60\u7684\u5730\u56fe\uff08M\uff09\u4e0a\uff1a\u53bb\u54ea\u91cc\uff0c\u4e0e\u8c01\u6218\u6597\u3002", ". Your orders will be on your map (M): where to go, who to fight."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u5df2\u7ecf\u5728\u4e00\u573a\u6218\u4e89\u4e2d\u83b7\u5f97\u4e86\u91d1\u724c\u3002\u6211\u7684\u4eba\u6c11\u6d41\u8840\u5df2\u7ecf\u591f\u591a\u4e86\u3002", "I've taken gold for one war already. My people bleed enough."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4e0a\u5e1d\u89c6\u56fe\uff1a\u65e0\u6cd5\u94a9\u4f4f\u9f20\u6807\uff0c\u6743\u529b\u571f\u5730\u5c06\u653e\u7f6e\u5728\u5e73\u9762\u5730\u56fe\u4e0a\uff1a ", "god view: could not hook the mouse, powers land where the flat map would put them: "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5df2\u6682\u505c\uff1a\u89c6\u56fe\u540e\u9762\u6253\u5f00\u4e86\u4e00\u4e2a\u6e38\u620f\u7a97\u53e3\uff08Esc \u5c06\u5176\u5173\u95ed\uff09", "Paused: a game window is open behind the view (Esc closes it)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u638c\u8235 W/S \u822a\u884c A/D \u8f6e \u5207\u6362\u9635\u98ce LMB \u706b\u529b", "Steer W/S  Sail A/D  Wheel: gusts  LMB: fire"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("  \uff08\u6211\u8981\u67e5\u770b\u60a8\u6700\u559c\u6b22\u7684\u5185\u5bb9\uff0c[ ] \u5728\u5b83\u4eec\u4e4b\u95f4\u8df3\u8f6c\uff09", "  (shows your favorites; [ ] to jump between them)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u5df2\u7ecf\u89c1\u8fc7{num}\u5e74\u4e86\u3002\u4e16\u754c\u5df2\u7ecf\u53d1\u751f\u4e86\u5f88\u5927\u7684\u53d8\u5316\u3002", "I've seen {num} years. The world has changed so much."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8bf4\u6e05\u695a\uff1a\u627e\u5230\u8c01\u62a2\u52ab\u4e86\u6211\u5e76\u9762\u5bf9\u4ed6\u4eec\uff0c\u7136\u540e\u56de\u5230\u6211\u8eab\u8fb9\uff0c ", "To be clear: find who robbed me and face them, then come back to me, "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u975e\u5e38\u3002\u5b83\u6bd4\u4f60\u5f3a\u3002\u4e0e\u670b\u53cb\u4e00\u8d77\u6218\u6597\uff0c\u6216\u8005\u7528\u5f13\u8fdc\u8ddd\u79bb\u6218\u6597\u3002", "Very. It's stronger than you. Fight it with friends, or from a distance with a bow."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff1f *\u773c\u775b\u4eae\u4e86*\u544a\u8bc9\u4ed6\u4eec\u6211\u60f3\u5ff5\u4ed6\u4eec\u3002\u544a\u8bc9\u4ed6\u4eec\u6211\u5f88\u597d\uff01", "? *eyes light up* Tell them I miss them. Tell them I'm well!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff0c{warFlag.Holding} \u5176\u4ed6\u4eba\u62ff\u7740\u5b83\u3002", ", with {warFlag.Holding} others holding it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u60a8\u7684\u7ad9\u70b9\u5df2\u4e22\u5931\uff0c\u5e76\u4e14\u6ca1\u6709\u5269\u4f59\u53ef\u7528\u571f\u5730\u3002\u4f60\u7684\u6536\u8d39\u65e0\u6548\u3002", "Your site is lost, and there's no free land left. Your charge is void."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("#\u6b65\u884c\u901f\u5ea6\u5360\u751f\u7269\u5168\u901f\u7684\u4e00\u90e8\u5206\uff1b\u6309\u4f4f Shift \u8fd0\u884c", "# walking pace as a share of the creature's full speed; hold Shift to run"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u65f6\u4e0d\u65f6\u522e\u4e00\u9635\u98ce\uff1a\u98ce\u5439\u8fc7\uff0c\u6811\u53f6\u548c\u8349\u53f6\u65cb\u8f6c\uff0c\u8349\u6728\u5f2f\u66f2", "# now and then a gust of wind: streaks of wind, leaves and grass whirled along, the grass and trees bending"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u5f53\u4f60\u8d70\u8def\u65f6\u89c6\u91ce\u4f1a\u6ce2\u52a8\u591a\u5c11\uff0c0 \u65e0 .. 1 \u5b8c\u6574", "# how much the view bobs as you walk, 0 none .. 1 full"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8bbe\u7f6e\u83dc\u5355\uff1a\u65e0\u6cd5\u6309 Esc\uff08\u5b83\u5173\u95ed\u83dc\u5355\u5e76\u653e\u5f00\u751f\u7269\uff09\uff1a ", "settings menu: could not take Esc (it closes the menu and lets go of the creature): "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6ca1\u6709\u5730\u65b9\u5bb9\u7eb3\u53e6\u4e00\u4e2a\u4eba\uff1a\u4f60\u7684\u57ce\u9547\u9700\u8981\u4e00\u680b\u514d\u8d39\u7684\u623f\u5b50\u3002", "There's no room for another: your town needs a free house."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4eec{2}\u7684{0}\u3001{1}\u6ca1\u6709\u5c4b\u9876\u3002\u5e2e\u52a9\u6211\u4eec\u5efa\u8bbe\u3002", "{title}, {num3} of us in {((NanoObject)city).name} have no roof. Help us build."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7236\u6bcd\uff1f\u6211\u72ec\u81ea\u5728\u8fd9\u4e2a\u4e16\u754c\u4e0a\u9192\u6765\uff0c\u5c31\u50cf\u6211\u4eec\u7b2c\u4e00\u4e2a\u4e00\u6837\u3002", "Parents? I woke up in this world on my own, as the first of us did."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u5439\u54cd\u6218\u4e89\u53f7\u89d2*\u4f60\u6709\u4f60\u7684\u6218\u4e89\u3002\u6211\u4eec\u4ece\u6765\u6ca1\u6709\u8bf4\u8fc7\u8bdd\u3002", "*calls for the war horns* You have your war. We never spoke."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8c01\u997f\u4e86\uff0c\u5c31\u65e0\u6cd5\u5411\u8c01\u63d0\u4f9b\u98df\u7269\u3002\u8ba9\u4ed6\u4eec\u9760\u8fd1\uff08\u8ddf\u6211\u6765\uff09\u3002", "Whoever's hungry is too far off to hand food to. Bring them close (Follow me)."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5206\u4eab\u5305\u91cc\u7684\u98df\u7269\uff08\u5bb6\u5ead\u5730\u56fe\uff1aM\uff0c\u6216Shift+M\uff09\u3002", "Share food from your bag (the family map: M, or Shift+M)."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ed6\u4eec\u65e0\u6cd5\u4ece\u4ed6\u4eec\u6240\u5728\u7684\u5730\u65b9\u5230\u8fbe\u90a3\u91cc\uff08\u5728\u6c34\u7684\u53e6\u4e00\u8fb9\uff09\u3002", "They can't get there from where they are (it's across the water)."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u9700\u8981\u4e00\u628a\u65a7\u5b50\u6765\u780d\u6811\u3002\u5f92\u624b\u5c31\u53ef\u4ee5\u4e86\uff0c\u4f46\u662f\u8981\u6162\u6162\u6765\u3002", "You'll want an axe for the trees. Bare hands will do, but slowly."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u544a\u8bc9\u6211\u4ed6\u4eec\u8bf4\u4e86\u4ec0\u4e48\uff0c\u6211\u5f88\u5feb\u5c31\u4f1a\u4ece\u4ed6\u4eec\u7684\u8138\u4e0a\u770b\u5230\u3002", "You'll tell me what they said, and I'll see it in their face soon enough."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4efb\u4f55\u6811\u3002\u7528\u65a7\u5b50\u780d\u5b83\uff0c\u5982\u679c\u5fc5\u8981\u7684\u8bdd\uff0c\u4e5f\u53ef\u4ee5\u5f92\u624b\u780d\u5b83\u3002", "Any tree. Chop it with an axe, or your bare hands if you must."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u5df2\u7ecf\u7b54\u5e94\u4e86{5}\u4eba\u4e86\u3002\u5148\u628a\u4e8b\u60c5\u505a\u5b8c\uff0c\u7136\u540e\u518d\u95ee\u6211\u3002", "You've promised {5} people already. Finish something first, then ask me."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4eec\u7684\u6d77\u5cb8\u4e0a\u5df2\u7ecf\u6ca1\u6709\u7a7a\u95f2\u7684\u571f\u5730\u4e86\u3002\u8fde\u5c71\u90fd\u6ca1\u6709\u8fc7\u53bb\u3002", "There's no free land left on our shores. Not even past the hills."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u5c0f\u5730\u56fe\u5230\u8fbe\u7684\u8ddd\u79bb\uff08\u4ee5\u4ece\u60a8\u5230\u5176\u8fb9\u7f18\u7684\u56fe\u5757\u4e3a\u5355\u4f4d\uff09", "# how far the minimap reaches, in tiles from you to its rim"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4eec\u6b63\u5728\u4e0e\u4ed6\u4eec\u4ea4\u6218\u3002\u5148\u628a\u4ed6\u4eec\u7559\u4e0b\uff0c\u7136\u540e\u6211\u4eec\u518d\u8c08\u3002", ", and we're at war with them. Leave them first, and then we'll talk."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u628a\u624b\u653e\u5728\u809a\u5b50\u4e0a*\u611f\u89c9\u5230\u4e86\u5417\uff1f\u6211\u4eec\u7684\u5c0f\u5b9d\u8d1d\u6765\u4e86 ", "*puts your hand on the belly* Feel that? Our little one comes "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4eec\u6709 {num2} \u4eba\u3002\u6ca1\u6709\u5bf9\u4efb\u4f55\u4eba\u8bf4\u4e00\u53e5\u8bdd\u3002", "There are {num2} of us. Not a word to anyone."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u5bb6\u4eba\u65e0\u6cd5\u4ece\u4ed6\u4eec\u6240\u5728\u7684\u5730\u65b9\u627e\u5230\u4f60\uff1b\u4ed6\u4eec\u4f1a\u7b49\u5f85\u3002", "Your family can't get to you from where they are; they'll wait."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7b2c\u4e00\u4eba\u79f0\u7684\u94a5\u5319\uff1b V \u548c F2 \u5728\u5730\u56fe\u4e0a\u4e5f\u8d77\u4f5c\u7528", "The keys in first person; V and F2 work on the map too"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u6807\u8bb0\u6218\u58eb\u90fd\u65e0\u6cd5\u5230\u8fbe\u90a3\u4e2a\u5730\u9762\uff1a\u5b83\u5728\u6c34\u7684\u53e6\u4e00\u8fb9\u3002", "None of your marked warriors can reach that ground: it's across the water."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6807\u8bb0\u8239\u53ea\uff0c\u7136\u540e\u53f3\u952e\u5355\u51fb\uff1a\u5728\u6c34\u4e2d\u822a\u884c\uff0c\u5411\u654c\u4eba\u5f00\u706b\u3002", "Mark ships, then right-click: water to sail, an enemy to fire on it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u5ba1\u89c6\u4f60*\u4f60\u5df2\u7ecf\u627f\u62c5\u4e86\u5f88\u591a\u627f\u8bfa\u3002\u53ef\u4ee5\u518d\u62ff\u4e00\u5f20\u5417\uff1f", "*looks you over* You're carrying a lot of promises already. Can you take one more?"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("{0} {1}\u7684\u519b\u961f\u805a\u96c6\uff1a{3}.{4}\u7684{2}", "{text4} The army of {((NanoObject)city).name} gathers: {order.Soldiers} of {order.Wanted}.{text3}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u4eba\u5934\u8981\u51fa\u4ef7\u3002\u5728\u7d22\u8981\u6211\u4eec\u7684\u571f\u5730\u4e4b\u524d\u5148\u7f34\u7eb3\u7f5a\u6b3e\u3002", "There's a price on your head. Pay your fine before you ask for our land."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("#\u4f60\u7684\u7231\u4eba\u548c\u5b69\u5b50\u4e0e\u4f60\u540c\u884c\uff0c\u5e76\u5728\u4f60\u79bb\u5f00\u6216\u52a0\u5165\u57ce\u9547\u65f6", "# your lover and children walk with you, and leave or join a town when you do"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("E:\u8c08\u8bdd|R:\u8c03\u60c5|T:\u62db\u52df|F:\u4fae\u8fb1|Q:\u7a83\u53d6", "E:Talk|R:Flirt|T:Recruit|F:Insult|Q:Steal"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u89e6\u6478\u63a7\u5236\uff1a\u5de6\u62c7\u6307\u884c\u8d70\uff0c\u53f3\u62d6\u52a8\u67e5\u770b\uff1b\u66f4\u591a\u6309\u952e\u5de6\u4e0a\u89d2", "Touch controls: left thumb walks, drag on the right to look; more keys top left"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("E:\u4ea4\u8c08|R:\u8c03\u60c5|T:\u62db\u52df|F:\u4fae\u8fb1|Q:\u7a83\u53d6", "E:Talk|R:Flirt|T:Recruit|F:Insult|Q:Steal"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff08\u8be5\u751f\u7269\u6ca1\u6709\u81ea\u5df1\u7684\u6b66\u5668\u914d\u7f6e\uff0c\u7528\u53cc\u624b/\u5f53\u524d\u6b66\u5668\uff09", "(this creature has no weapons of its own; uses fists / current weapon)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff08\u7a7a\uff09\u2014\u2014 \u53bb\u780d\u6811\u3001\u91c7\u96c6\u3001\u8d2d\u4e70\u540e\u8fd9\u91cc\u4f1a\u663e\u793a\u7269\u54c1", "(empty) \u2014 chop trees, gather or buy; items will show up here"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u88ab\u62a2\u52ab\u4e86\uff0c\u5c0f\u5077\u5374\u900d\u9065\u6cd5\u5916\u3002\u6211\u4ec0\u4e48\u90fd\u6ca1\u6709\u5269\u4e0b\u4e86", ", I was robbed and the thief walks free. I've nothing left."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u76b1\u7709*\u6709\u4eba\u5df2\u7ecf\u5728\u90a3\u7247\u571f\u5730\u4e0a\u5b9a\u5c45\u4e86\u3002\u65e0\u5904\u53ef\u53bb\u3002", "*frowns* Someone's settled that land already. There's nowhere left."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u8fd9\u91cc\u7684\u5728\u4f18\u8d28\u7684\u7a7a\u5730\uff08E\uff09\u4e0a\u5efa\u7acb\u6751\u5e84\u5e76\u9886\u5bfc\u5b83\u3002", " of here. Raise the village on good free land (E), and lead it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u60a8\u6574\u591c\u7761\u5f97\u5f88\u9999\uff0c\u9192\u6765\u65f6\u7cbe\u795e\u7115\u53d1\u3001\u7cbe\u795e\u9971\u6ee1\u3002*", "*You sleep soundly through the night, and wake rested and whole.*"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u738b\u51a0\u7684\u4fdd\u62a4\u662f\u4f60\u7684\u3002\u4fdd\u6301\u548c\u5e73\uff0c\u4e00\u5207\u90fd\u4f1a\u4fdd\u6301\u4e0b\u53bb\u3002", "The crown's protection is yours. Keep the peace and it stays that way."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u201c\u7ee7\u7eed\u4f60\u7684\u4e00\u5929\u3002\u201d\u4f60\u7684\u5bb6\u4eba\u53c8\u56de\u5230\u4e86\u4ed6\u4eec\u7684\u751f\u6d3b\u3002", "\"Go about your day.\" Your family goes back to their lives."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8001\u77f3\u5934\u56de\u5e94\u4f60\u7684\u624b\u3002\u9009\u62e9\u4e00\u4e2a\u6751\u5e84\uff0c\u5929\u5c31\u4f1a\u584c\u4e0b\u6765\u3002", "The old stone answers your hand. Choose a village and the sky will fall on it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u79cd\u690d\u3002\u6807\u8bb0\u6218\u58eb\u5e76\u53f3\u952e\u5355\u51fb\u5b83\u53ef\u4ee5\u8ba9\u4ed6\u4eec\u6293\u4f4f\u5b83\u3002", " planted. Mark warriors and right-click it to send them to hold it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7ed9\uff0c\u6536\u56de\u53bb\u3002 {num2} \u91d1\u8272\u3002\u522b\u544a\u8bc9\u8b66\u536b\uff01", "Here, take it back. {num2} gold. Don't tell the guards!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u8bbe\u7f6e\u83dc\u5355 (F2) \u5df2\u6253\u5f00\uff1a\u5730\u56fe\u4e0d\u518d\u63d0\u9192\u60a8", "# the settings menu (F2) has been opened: the map stops reminding you of it"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6807\u8bb0\u6ce8\u89c6\u76ee\u6807\uff08\u671b\u8fdc\u955c\u4e0b\u4e5f\u53ef\uff09\uff1b\u957f\u6309\u6253\u5f00\u6807\u8bb0\u83dc\u5355", "Ping what you look at, binoculars too; hold: ping menu"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u663e\u793a\u5c4f\u5e55\u6447\u6746\u548c\u6309\u94ae\uff1b\u81ea\u52a8\uff1a\u624b\u673a\u6216\u89e6\u6478\u5c4f\u5e55\u65f6\u542f\u7528", "On-screen stick and buttons; Auto: on a phone, or once you touch the screen"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u60f3\u8981\u6211\u4eec\u7684\u5251\u5728\u4f60\u80cc\u540e\u5417\uff1f\u8fd9\u6837\u5c31\u53ef\u4ee5\u5b89\u6392\u4e86\u3002", "Want our swords at your back? That can be arranged."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u591c\u665a\u8fc7\u53bb*\u5230\u4e86\u65e9\u4e0a\uff0c\u6709\u4e00\u4e2a\u5c0f\u5bb6\u4f19\u5728\u4f60\u8eab\u8fb9\uff01", "*the night passes* By morning, there's a little one with you!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u4ed4\u7ec6\u60f3\u60f3*\u6211\u4eec\u5df2\u7ecf\u6210\u957f\u4e86\u3002\u662f\u65f6\u5019\u6709\u4eba\u8d70\u4e86\u3002", "*thinks it over* We've grown. It's time someone went."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4eec\u6709 {count} \u7528\u6211\u4eec\u7684\u8bed\u8a00\u5199\u7684\u4e66\u3002", "We've {count} books written in our tongue."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4ece\u6765\u6ca1\u6709\u7236\u6bcd\u3002\u4ed6\u4eec\u8bf4\uff0c\u8bf8\u795e\u628a\u6211\u5b89\u7f6e\u5728\u8fd9\u91cc\u3002", "I never had parents. The gods set me down here, they say."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u66fe\u7ecf\u6740\u8fc7{num}\u3002\u4e8b\u60c5\u5e76\u6ca1\u6709\u53d8\u5f97\u66f4\u5bb9\u6613\u3002", "I've killed {num} in my time. It doesn't get easier."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("{0}\u5c06\u62a4\u536b\u4f60{1}\u5e74\uff1a\u8ddf\u968f\u4f60\u5e76\u653b\u51fb\u4f60\u7684\u654c\u4eba", "{0} guards you for {1} year{2}: they follow you and fight whoever fights you"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6ca1\u6709\u4e1c\u897f\u5403\u3002\u91c7\u6458\u6d46\u679c\u6216\u72e9\u730e\uff0c\u6216\u52a0\u5165\u4e00\u5ea7\u57ce\u5e02\u3002", "Nothing to eat. Pick berries or hunt, or join a city."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5de6\u952e\uff1a\u9009\u62e9\u4e00\u4e2a\u62d6\u52a8\uff1a\u79fb\u52a8\u6eda\u8f6e\uff1a\u7f29\u653e\u53f3\u952e\uff1a\u7b49\u5f85", "Left: pick one   Drag: move   Wheel: zoom   Right click: wait there"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7ed9\u6211\u5e26\u6765 {q.Need} {Res(q)}", "bring me {q.Need} {Res(q)}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u57ce\u5e02\u4e0d\u80fd\u9976\u6055\u4efb\u4f55\u4eba\uff1a\u519b\u8425\u5df2\u6ee1\u6216\u7cae\u4ed3\u592a\u7a7a\u3002", "Your cities can't spare anyone: the barracks are full or the granaries too empty."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff01\u4f60\u7684\u58eb\u5175\u8ddf\u968f\u4f60\u3002\u4ece\u4f60\u7684\u5730\u56fe\uff08M\uff09\u6307\u6325\u4ed6\u4eec\u3002", "! Your soldiers follow you. Command them from your map (M)."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u5df2\u7ecf\u6709\u571f\u5730\u53ef\u4ee5\u5b9a\u5c45\u4e86\u3002\u770b\u770b\u4f60\u7684\u5730\u56fe\uff08M\uff09\u3002", "You already have land to settle. Look at your map (M)."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4e0d\u4f1a\u76f8\u4fe1\u4f60\u6709\u4e00\u4e2a\u6728\u68da\uff0c\u66f4\u4e0d\u7528\u8bf4\u4e00\u4e2a\u6751\u5e84\u4e86\u3002", "I wouldn't trust you with a woodshed, never mind a village."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4e16\u754c\u65b0\u95fb\uff1a\u738b\u56fd\u3001\u56f4\u57ce\u3001\u6218\u4e89\uff1b\u70b9\u51fb\u6761\u76ee\u8fdb\u884c\u6807\u8bb0", "World news: your realm, sieges, wars; click a line to mark it"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f7f\u7528 CPU \u6e32\u67d3\uff0c\u6216\u4f7f\u7528 GPU \u63d0\u9ad8\u5e27\u7387", "Draw on the processor, or on the graphics card for more frames"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u76f8\u5bf9\u4e8e\u751f\u7269\u5168\u901f\u7684\u6bd4\u4f8b\uff1b\u6309\u4f4f Shift \u5954\u8dd1", "Of the creature's full speed; Shift runs"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6e38\u620f\u65c1\u7ed8\u56fe\u518d\u6b21\u5931\u8d25\uff1b\u4ece\u73b0\u5728\u5f00\u59cb\u6309\u6b65\u9aa4\u7ed8\u5236\uff1a ", "drawing beside the game failed again; drawing in step from now on: "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f02\u6b65\u6e32\u67d3\u5931\u8d25\uff1a\u5df2\u5207\u6362\u540c\u6b65\u6e32\u67d3\uff0c\u91cd\u542f\u6e38\u620f\u540e\u6062\u590d", "Async render failed: switched to sync; restored after restart"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u3002\u60a8\u7ee7\u627f\u4e86 {_deadMoney} \u91d1\u5e01\u3002", " You inherited {_deadMoney} gold."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("3D\u4e16\u754c\u89c2\u5931\u8d25\uff1b\u8fd4\u56de\u5e73\u9762\u5730\u56fe\uff08V \u518d\u8bd5\u4e00\u6b21\uff09", "3D world failed; back to flat map (V to try again)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6839\u987b\u6293\u4f4f\u4f60\u6240\u7784\u51c6\u7684\u6bcf\u4e00\u4e2a\u654c\u4eba\uff0c\u8349\u4e1b\u4f1a\u957f\u51fa\u6765", "Roots grab every foe where you aim, and grass springs up"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6cbb\u6108\u4f60\u81ea\u5df1\u548c\u4f60\u7684\u4eb2\u4eba\uff1b\u5feb\u811a\u4e00\u4f1a\u513f\uff1b\u8349\u957f\u8d77\u6765", "Heal yourself and your kin; quick feet for a while; grass springs up"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u591c\u665a\u8fc7\u53bb\u4e86* ...\u8fd9\u6b21\u4e0d\u884c\u3002\u603b\u6709\u660e\u5929\u3002", "*the night passes* ...Not this time. There's always tomorrow."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u624b\u8868\uff0c\u7741\u5927\u773c\u775b*\u4e00\u4e2a\u65b0\u7684\u5c0f\u5bb6\u4f19\uff01\u770b\u770b\u5b83\uff01", "*watches, wide-eyed* A new little one! Look at it!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4e00\u4e2a\u65b0\u6751\u5e84...*\u629a\u6478\u4e0b\u5df4*\u662f\u7684\u3002\u6709\u7a7a\u5730\u3002", "A new village... *strokes chin* Yes. There's free land."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u51fa\u4e86\u70b9\u95ee\u9898\u3002\u4f20\u4ee4\u5b98\u4e0d\u4f1a\u9a91\u9a6c\u3002\u4fdd\u7559\u4f60\u7684\u9ec4\u91d1\u3002", "Something's wrong. The heralds won't ride. Keep your gold."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u5305\u91cc\u6ca1\u6709\u4e1c\u897f\u53ef\u4ee5\u5356\u3002\u53bb\u6536\u96c6\u4e00\u4e9b\u4e1c\u897f\u5427\u3002", "You've nothing in your bag to sell. Go gather something."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4fdd\u62a4\u662f\u6709\u4ee3\u4ef7\u7684\u3002\u738b\u5ba4\u7684\u58eb\u5175\u4e0d\u662f\u514d\u8d39\u884c\u519b\u7684\u3002", "Something else about protection."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5408\u540c\u5230\u671f\u3002 \uff08\u4e0e\u4ed6\u4eec\u4ea4\u8c08\u4ee5\u518d\u6b21\u96c7\u7528\u4ed6\u4eec\u3002\uff09", "'s contract is up. (Talk to them to hire them again.)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4f1a\u4ed8\u7f5a\u6b3e\u7684\u3002 \uff08{bounty} \u91d1\u8272\uff09", "I'll pay my fine. ({bounty} gold)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65e0\u6cd5\u63a5\u7ba1\u6b65\u884c\u6b65\u9aa4\uff0c\u4f60\u9644\u8fd1\u7684\u751f\u7269\u4fdd\u6301\u6e38\u620f\u8282\u594f", "could not take over the walking step, the creatures near you keep the game's pace"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65e0\u6cd5\u63a5\u7ba1\u6218\u6597\u6b65\u9aa4\uff0c\u4f60\u64cd\u63a7\u7684\u751f\u7269\u4ecd\u53ef\u81ea\u884c\u6218\u6597", "could not take over the fighting steps, the creature you control may still fight by itself"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65e0\u6cd5\u5173\u6ce8\u4e16\u754c\u65e5\u5fd7\uff0c\u65b0\u95fb\u7a97\u53e3\u4ec5\u663e\u793a\u4fdd\u5b58\u7684\u5185\u5bb9", "could not follow the world log, the news window shows only what the save holds"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5bf9\u4e8e\u50cf\u4f60\u8fd9\u6837\u7684\u4eba\u6765\u8bf4\uff0c\u8fd9\u5e94\u8be5\u662f\u5f88\u5feb\u7684\u5de5\u4f5c\u3002", "For someone like you, this should be quick work."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u5f88\u597d\uff0c\u6211\u60f3\u4ed6\u4eec\u3002\u5c31\u8fd9\u6837\u3002\u4ed6\u4eec\u4f1a\u5f88\u9ad8\u5174\u7684\u3002", "That I'm well, that I think of them. That's all. They'll be glad of it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4eba\u4eec\u4f1a\u542c\u8bf4\u5b83\uff08{q.Renown} \u540d\u58f0\uff09", ", and people will hear of it ({q.Renown} renown)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u770b\u8d77\u6765\u5df2\u7ecf\u591f\u5fd9\u4e86\u3002\u7b54\u5e94\u522b\u4eba\u7684\u4e8b\u60c5\u5148\u5b8c\u6210\u3002", "You look busy enough already. Finish what you've promised others first."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5173\u4e8e\u7ed9\u4f60\u7684\u4e00\u573a\u6bd4\u8d5b\u3002\u4e0d\u8981\u8ba9\u5b83\u8ba9\u4f60\u9677\u5165\u56f0\u5883\u3002", "About a match for you. Don't let it corner you."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5c31\u5728\u90a3\u91cc\uff0c\u5982\u679c\u4f60\u770b\u7684\u8bdd\u3002\u4f60\u7684\u5305\u80fd\u88c5\u5f97\u4e0b\u5b83\u3002", "Out there, if you look. Your bag will hold it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5230\u76ee\u524d\u4e3a\u6b62 {1} \u7684 {0}\u3002\u7ee7\u7eed\u4f20\u6559\u3002", "{q.Have} of {q.Need} so far. Keep preaching."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u671b\u8fdc\u955c\uff1a\u957f\u6309\u4f7f\u7528\uff0c\u8f7b\u6309\u6301\u7eed\u4f7f\u7528\uff08\u6eda\u8f6e\u7f29\u653e\uff09", "Binoculars: hold, or tap to keep them up (wheel zooms)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u9644\u8fd1\u751f\u7269\u6309\u6b64\u6bd4\u4f8b\u884c\u8d70\uff1b\u6218\u6597\u548c\u9003\u8dd1\u4ecd\u4fdd\u6301\u5168\u901f", "Creatures near you walk at this share of their pace; fights and fleeing stay quick"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5c0f\u5730\u56fe\u6253\u5f00\uff08N\u9690\u85cf\u5b83\uff1b\u6309\u4f4fN\u67e5\u770b\u6574\u4e2a\u5730\u56fe\uff09", "Minimap on   (N hides it; hold N for the whole map)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u4e0a\u4e0b\u6253\u91cf\u4f60*\u6211\u4eec\u5728\u8fd9\u91cc\u4fdd\u6301\u81ea\u5df1\u7684\u98ce\u683c\u3002", "*looks you up and down* We keep to our own here."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u628a\u624b\u653e\u5728\u4f60\u7684\u809a\u5b50\u4e0a*\u6211\u4eec\u7684\u5c0f\u5bb6\u4f19\u6765\u4e86 ", "*puts a hand on your belly* Our little one comes "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6ca1\u6709\u7a7a\u95f4\u5bb9\u7eb3\u53e6\u4e00\u4e2a\u4eba\uff08\u57ce\u9547\u6216\u4e16\u754c\u5df2\u6ee1\uff09\u3002", "There is no room for another (the town or the world is full)."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd9\u573a\u6218\u4e89\u593a\u8d70\u4e86\u6211\u4eec\u7684\u513f\u5b50\u3002\u5be1\u5987\u9700\u8981\u9762\u5305\u3002", ", this war takes our sons. The widows need bread."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff0c\u4e00\u573a\u76db\u5bb4\uff01\u4eba\u4eec\u60f3\u8981\u4e00\u573a\u76db\u5bb4\u6765\u632f\u594b\u4eba\u5fc3\u3002", ", a feast! The people want a feast to lift their hearts."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4e00\u4e2a\u964c\u751f\u4eba\u2026\u2026\u662f\u4ec0\u4e48\u98ce\u628a\u4f60\u5439\u5230\u8fd9\u91cc\u6765\u7684\uff1f", "A stranger... what brings you here?"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5982\u679c\u4f60\u95ee\u6211\u7684\u8bdd\uff0c\u8fd9\u662f\u4e16\u754c\u4e0a\u6700\u597d\u7684\u5730\u65b9\u3002", " is the best place in the world, if you ask me."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6709\u4e00\u5929\uff0c\u6574\u4e2a\u56fd\u5bb6\u7684\u4eba\u4eec\u90fd\u4f1a\u77e5\u9053\u6211\u7684\u540d\u5b57\u3002", "One day they'll know my name across the whole land."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u6700\u559c\u6b22\u7684\u4e8b\u60c5\u662f\u6f2b\u957f\u7684\u4e00\u5929\u540e\u5403\u4e00\u987f\u70ed\u996d\u3002", "My favorite thing is a warm meal after a long day."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u519b\u961f\u9700\u8981\u58eb\u5175\uff0c\u9700\u8981\u5b9a\u5c45\u8005\u5efa\u7acb\u65b0\u7684\u6751\u5e84\u3002", " needs soldiers for its army, and settlers to found new villages."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u76b1\u7709*\u519b\u9700\u5b98\u8bf4\u6ca1\u6709\u4f60\u7684\u4f4d\u7f6e\u3002\u4e0d\u662f\u4eca\u5929\u3002", "*frowns* The quartermaster says there's no place for you. Not today."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff08\u5728\u6811\u4e0a\u9009\u62e9\u4e00\u4e2a\u4eba\u5e76\u5728\u6307\u5357\u9488\u4e0a\u6807\u8bb0\u4ed6\u4eec\uff09", "(Pick someone on the tree to mark them on your compass)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4eec\u6709 {num} \u5b69\u5b50\uff1a{text}\u3002", "We have {num} children: {text}."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4f1a\u4ed8\u94b1\u7ed9\u4f60\uff0c\u8ba9\u4f60\u5bf9\u53e6\u4e00\u4e2a\u738b\u56fd\u53d1\u52a8\u6218\u4e89\u3002", "I'd pay you to make war on another realm."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd8\u8bb0\u5f97\u5417\uff1f\u6211\u4e0d\u8bb0\u5f97\u592a\u591a\u4e86\u3002\u4eca\u5929\u5c31\u662f\u4eca\u5929\u3002", "Remember? I don't remember much. Today is today."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u54e6\u3002\u66f4\u591a\u8fd9\u6837\u7684\u4e8b\u60c5\uff0c\u6211\u4eec\u5c31\u4f1a\u6210\u4e3a\u597d\u670b\u53cb\u3002", "Ooh. More of this, and we'll be fast friends."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u91c7\u96c6\u6d46\u679c\u6216\u72e9\u730e\u6765\u5582\u517b\u5b83\u4eec\uff0c\u6216\u5728\u57ce\u9547\u5b9a\u5c45\u3002", "Gather berries or hunt to feed them, or settle in a town."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6309\u4f4f C \u6216\u9f20\u6807\u4e2d\u952e\u542f\u52a8 ping \u8f6e\u3002", "Hold C or the middle mouse button for the ping wheel."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u53f3\u952e\u5355\u51fb\u5730\u56fe\uff1a\u4f60\u7684\u58eb\u5175\u524d\u5f80\u90a3\u91cc\u5e76\u5360\u9886\u5b83\u3002", "Right-click the map: your soldiers march there and hold it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u53f3\u952e\u5730\u56fe\u63d2\u65d7\u3002\u6bcf\u4e2a\u4eba\u90fd\u6709\u81ea\u5df1\u7684\u6218\u58eb\u961f\u4f0d\u3002", "Right-click the map to plant a flag. Each holds its own band of warriors."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6ca1\u6709\u6218\u4e89\u3001\u56f4\u653b\u6216\u5f81\u670d\u53ef\u8a00\u3002\u613f\u5b83\u6301\u7eed\u5f88\u4e45\u3002", "No wars, sieges or conquests to tell of. Long may it last."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65e0\u6cd5\u6302\u94a9\u5360\u6709\u8f93\u5165\uff0c\u8fd0\u52a8\u4fdd\u6301\u4e0e\u4e16\u754c\u76f8\u5173\uff1a ", "could not hook possession input, movement stays world-relative: "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65e0\u6cd5\u63a5\u7ba1\u624b\u673a\u68d2\uff0c\u7b2c\u4e00\u4eba\u79f0\u65e0\u6cd5\u5728\u624b\u673a\u4e0a\u884c\u8d70", "could not take over the phone's stick, first person can't walk on a phone build"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65e0\u6cd5\u63a5\u7ba1\u7834\u6298\u53f7\u952e\uff0cShift \u4ecd\u7136\u7834\u6298\u53f7", "could not take over the dash key, Shift still dashes"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7531\u4f60\u5236\u4f5c\uff0c\u5f53\u4f60\u56de\u5230\u6211\u8eab\u8fb9\u65f6\u63e1\u5728\u4f60\u624b\u91cc\uff0c ", ", made by you, held in your hand when you come back to me, "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u7b11*\u7528\u4ec0\u4e48\uff1f\u53f2\u5bc6\u65af\u7684\u961f\u5217\u957f\u8fbe\u4e00\u4e2a\u8d5b\u5b63\u3002", "*laughs* With what? And the smith's queue is a season long."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u6b7b\u4e86\u6211\u5c31\u77e5\u9053\u4e86\u3002\u7136\u540e\u6765\u627e\u6211\u8981\u4f60\u7684\u5de5\u8d44\u3002", " is dead, I'll know. Then come to me for your pay."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6709\u4eba\u62a2\u52ab\u6211\uff01\u5149\u5929\u5316\u65e5\u4e4b\u4e0b\u62ff\u8d70\u4e86\u6211\u7684\u79ef\u84c4\u3002", "Someone robbed me! Took my savings in broad daylight."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u56fd\u5e93\u548c\u56fd\u738b\u7684\u94b1\u5305\u90fd\u7a7a\u4e86\uff1a\u8fd9\u6b21\u6ca1\u6709\u9ec4\u91d1\u4e86\u3002", "The treasury and the king's purse are empty: no gold this time."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7b2c\u4e00\u4eba\u79f0\u4e2d\u7684\u5168\u90e8\u58f0\u97f3\uff0c\u5305\u62ec\u6e38\u620f\u672c\u8eab\u7684\u58f0\u97f3", "All you hear in first person, the game too"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u654c\u4eba\u663e\u793a\u7ea2\u8272\uff0c\u670b\u53cb\u663e\u793a\u84dd\u8272\uff0c\u5bb6\u4eba\u663e\u793a\u7eff\u8272", "Red over foes, blue over friends, green over your family"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6e38\u620f\u65c1\u8fb9\u7684\u571f\u5730\u5237\u65b0\u5931\u8d25\uff08\u8fdb\u884c\u4e0b\u4e00\u5e27\uff09\uff1a ", "land refresh beside the game failed (it carries on next frame): "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u6536\u8d77\u4f60\u6240\u6301\u6709\u7684\u4e1c\u897f\uff08H\u6216\u70b9\u51fb\u5c06\u5176\u62ff\u8d77\uff09", "You put away what you were holding   (H or click to take it up)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("W/S:\u8239\u5e06|A/D:\u8239\u8235|LMB:\u5f00\u706b", "W/S:Sail|A/D:Rudder|LMB:Fire"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \uff08{magnitude:F1} \u74f7\u7816\uff09", " ({magnitude:F1} tiles)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u58eb\u5175\uff08{num}\uff09\u524d\u5f80\u90a3\u91cc\u5e76\u5360\u9886\u5b83\u3002", "Your soldiers ({num}) march there and hold it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5b89\u9759\u6d4b\u8bd5\u526f\u672c\uff1a\u5728\u540e\u53f0\u8fd0\u884c\uff0c\u9759\u97f3\uff0c\u6587\u4ef6\u5728 ", "quiet test copy: runs in the background, muted, files in "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4fdd\u62a4\uff1f\u6211\u662f\u4f60\u6700\u597d\u7684\u9009\u62e9\u3002\u4e3a\u4e86\u4e00\u4e2a\u4ef7\u683c\u3002", "Protection? I'm your best option. For a price."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65f6\u4ee3\u5371\u9669\u3002\u6211\u4f1a\u5b88\u62a4\u4f60\u7684\u80cc\u540e\uff0c\u4e3a\u4e86\u9ec4\u91d1\u3002", "Dangerous times. I'll watch your back, for gold."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u662f\u9547\u4e0a\u7684\u65b0\u4e8b\u7269\u3002\u8c01\u77e5\u9053\u662f\u4ece\u54ea\u91cc\u6765\u7684\u3002", " is new in town. Came from who knows where."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u53ea\u662f{num}\uff0c\u6211\u7684\u4eba\u751f\u8fd8\u5728\u540e\u9762\u5462\uff01", "I'm only {num}, I've got my whole life ahead of me!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u90a3\u5929\u4f60\u6709\u611f\u89c9\u5230\u5927\u5730\u9707\u52a8\u5417\uff1f\u5947\u602a\u7684\u65f6\u4ee3\u3002", "Did you feel the earth shake the other day? Strange times."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u66fe\u7ecf\u8fd1\u8ddd\u79bb\u95fb\u8fc7\u9f99\u7684\u6c14\u606f\u5417\uff1f\u6211\u6709\u3002\u4e00\u6b21\u3002", "Ever smelled a dragon's breath up close? I have. Once."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f4f\u624b\u5427\uff0c\u4eba\u4eec\u90fd\u770b\u7740\u5462\uff01 \u2026\u2026\u522b\u505c\u4e0b\u6765\u3002", "Stop it, people are watching! ...don't stop."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \uff08\u7a7a\u5730\u4e0a\u7684 E\uff09\u3002 M \u6307\u660e\u4e86\u9053\u8def\u3002", " (E on free land). M shows the way."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6218\u4e89\u4e2d\u79bb\u5f00\uff1f\u5176\u4ed6\u4eba\u5219\u4ee5\u66f4\u5c11\u7684\u94b1\u88ab\u7ede\u6b7b\u3002", "Leave in the middle of a war? Others have hanged for less."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6ca1\u6709\u9ec4\u91d1\u53ef\u4ee5\u4ece\u548c\u5e73\u4e3b\u4e49\u8005\u90a3\u91cc\u4e70\u5230\u6218\u4e89\u3002", "No gold buys a war from a pacifist."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u593a\u8d70\u4e86\u4e00\u6761\u751f\u547d\u3002\u4e00\u6b21\u3002\u6211\u7ecf\u5e38\u60f3\u8d77\u5b83\u3002", "I've taken a life. Once. I think of it often."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6ca1\u4ec0\u4e48\u53ef\u5356\u7684\u3002\u6709\u94c1\u5417\uff1f\u81ea\u5df1\u5236\u4f5c\uff08I\uff09\u3002", "Nothing to sell. Got iron? Craft it yourself (I)."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u653e\u8fdb\u53e3\u888b*\u4ec0\u4e48\u6d77\u62a5\uff1f\u4ee5\u524d\u4ece\u672a\u89c1\u8fc7\u4f60\u3002", "*pockets it* What poster? Never seen you before."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u5bb6\u4eba\u4e0d\u80fd\u8ddf\u7740\u4f60\u6765\u8fd9\u91cc\uff1b\u4ed6\u4eec\u4f1a\u7b49\u4f60\u3002", "Your family can't follow you here; they'll wait for you."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65e0\u6cd5\u63a5\u7ba1\u6240\u62e5\u6709\u7684\u6b65\u4f10\uff0c\u4f60\u7684\u6b65\u4f10\u8ddf\u968f\u5e27\u7387", "could not take over the possessed step, your pace follows the frame rate"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6b65\u884c\uff1b\u6211\u4f1a\u8ddf\u4e0a\u7684\u3002\u522b\u4e22\u4e0b\u6211\u4e00\u4e2a\u4eba\u8dd1\u6389\u3002", "Walk; I'll keep up. Don't run off and leave me behind."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u662f\u4ed6\u4eec\u7684\u9996\u90fd\uff1a\u5b83\u4e0d\u4f1a\u53cd\u6297\u81ea\u5df1\u7684\u56fd\u738b\u3002", " is their capital: it won't rise against its own king."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6d41\u661f\u4e0e\u95ea\u7535\u5e76\u5b58\u3002\u51e0\u4e4e\u6ca1\u6709\u4ec0\u4e48\u4f1a\u7559\u4e0b\u6765\u3002", "Meteors and lightning together. Little will be left standing."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65b9\u5c16\u7891\u53d1\u51fa\u567c\u556a\u58f0\u3002\u9ed1\u8272\u7684\u4e91\u5c42\u6cb8\u817e\u8d77\u6765 ", "The obelisk crackles. Black clouds boil up over "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u65e0\u8bba\u5982\u4f55\u90fd\u8981\u5728 5 \u79d2\u5185\u518d\u6b21\u5220\u9664\u5b83\u3002", " again within 5 seconds to drop it anyway."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u7b11*\u4f60\u662f\u56fd\u738b\u3002\u6574\u4e2a\u519b\u961f\u5df2\u7ecf\u662f\u4f60\u7684\u4e86\u3002", "*laughs* You're the king. The whole army is yours already."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5728{tile.x}\uff0c{tile.y}", " at {tile.x},{tile.y}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6751\u5e84\u9700\u8981\u6210\u719f\u7684\u53cc\u624b\u3002\u7b49\u4f60\u8001\u4e86\u518d\u56de\u6765\u5427\u3002", "A village needs grown hands. Come back when you're older."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u738b\u51a0\u652f\u4ed8{arg} {got} \u91d1\u5e01\u3002", "The crown pays{arg} {got} gold."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("# \u811a\u6b65\u58f0\u54cd\u5ea6\uff0c0 \u65e0\u58f0.. 1 \u5168\u54cd", "# footstep loudness, 0 silent .. 1 full"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ea4\u8c08\u3001\u8fdb\u5c4b\u3001\u767b\u8239\u3001\u5b58\u653e\u7269\u8d44\u3001\u67e5\u770b\u60ac\u8d4f\u677f", "Talk, enter, board, store your bag, read a bounty board"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u53ef\u89c1\u8ddd\u79bb\uff1b\u8fdc\u5904\u4e3b\u8981\u663e\u793a\u9ad8\u5927\u7269\u4f53\uff08F6\uff09", "How far you see; far off, what stands tall (F6)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5c06\u5730\u56fe\u663e\u793a\u4e3a\u4e09\u7ef4\u4e16\u754c\uff08\u5728\u5730\u56fe\u4e0a\u6309 V\uff09", "The map drawn as the 3D world (V on the map)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65e0\u6cd5\u5728\u7b2c\u4e00\u4eba\u79f0\u4e2d\u4fdd\u6301\u533a\u57df\u952e\u5173\u95ed X\uff1a ", "could not keep the zone keys off X in first person: "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u79fb\u52a8\u6302\u94a9\u4e0d\u53ef\u7528\uff1aWASD \u6cbf\u5730\u56fe\u8f74\u79fb\u52a8", "Movement hook unavailable: WASD moves along map axes"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("E:\u8c08\u8bdd|T:\u62db\u52df|F:\u4fae\u8fb1|Q:\u7a83\u53d6", "E:Talk|T:Recruit|F:Insult|Q:Steal"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5de5 \u5177\uff08\u5e38\u9a7b \u00b7 \u91c7\u96c6\u7528\uff0c\u7eff\u8272\u6807\u8bb0\uff09", "TOOLS (always kept \u00b7 for gathering, green tag)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6309\u4f4fX\u7784\u51c6\uff0c\u677e\u5f00\u5219\u6295\u63b7\u81ea\u5df1\u7684\u4e00\u6839\u9aa8\u5934", "Hold X to aim, let go to hurl one of your own bones"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u5468\u56f4\u7684\u4eb2\u4eba\u632f\u4f5c\u8d77\u6765\uff0c\u5411\u4f60\u7684\u654c\u4eba\u5c48\u670d", "Your kin around you take heart and fall on your foe"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u73b0\u5728\u4e0d\u884c\uff1a\u4f60\u592a\u997f\u4e86\uff0c\u6216\u8005\u8fd8\u6ca1\u51c6\u5907\u597d\u3002", "Not now: you're too hungry, or not ready."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u52aa\u529b\u5de5\u4f5c\uff0c\u4fdd\u6301\u5e73\u9759\uff0c\u4f60\u5c31\u53ef\u4ee5\u7559\u4e0b\u6765\u3002", "Work hard, keep the peace, and you can stay."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u73b0\u5728\u9886\u5bfc\u5c0f\u9547\u3002\u6211\u4eec\u4f1a\u770b\u770b\u60c5\u51b5\u5982\u4f55\u3002", " leads the town now. We'll see how that goes."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u652f\u4ed8\u6728\u6750\u548c\u5efa\u7b51\u5de5\u4eba\u7684\u8d39\u7528\uff0840\u91d1\u5e01\uff09", "Pay for timber and builders (40 gold)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4eca\u5929\u780d\u4f10\u4e86\u4e00\u6574\u7247\u68ee\u6797\u3002\u55ef\uff0c\u5dee\u4e0d\u591a\u4e86\u3002", "Chopped a whole forest today. Well, almost."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u6c38\u8fdc\u90fd\u4f1a\u544a\u8bc9\u4f60\u771f\u76f8\uff0c\u5373\u4f7f\u5b83\u523a\u75db\u4f60\u3002", "I'll always tell you the truth, even when it stings."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u66b4\u529b\u6c38\u8fdc\u89e3\u51b3\u4e0d\u4e86\u4efb\u4f55\u503c\u5f97\u89e3\u51b3\u7684\u4e8b\u60c5\u3002", "Violence never solved anything worth solving."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u773c\u775b\uff1f\u5f88\u957f\u7684\u6545\u4e8b\u3002\u4f60\u5e94\u8be5\u770b\u770b\u53e6\u4e00\u4f4d\u3002", "The eye? Long story. You should see the other one."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6709\u65f6\u6211\u60f3\u77e5\u9053\u662f\u8c01\u5728\u5b88\u62a4\u7740\u6211\u4eec\u6240\u6709\u4eba\u3002", "Sometimes I wonder who watches over us all."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u3002\u5728\u571f\u5730\u80a5\u6c83\u7684\u5730\u65b9\uff0c\u5efa\u9020\u6751\u5e84\uff08E\uff09\u3002", ". Where the land is good, raise the village (E)."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u90a3\u5c31\u4ea4\u547d\u4ee4\u5427\u3002\u4f60\u53c8\u662f\u4e00\u4e2a\u81ea\u7531\u516c\u6c11\u4e86\u3002", "Then hand in your orders. You're a free citizen again."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u53ef\u60dc\u4e86\u3002\u8fd9\u7247\u571f\u5730\u5c06\u7b49\u5f85\u66f4\u52c7\u6562\u7684\u811a\u6b65\u3002", "A pity. The land will wait for braver feet."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4eec\u57cb\u846c\u4e86\u6211\u4eec\u7684\u5b69\u5b50 {num2}\u3002", "We buried {num2} of our little ones."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4e0d\u518d\u662f\u4e86\u3002\u6ca1\u90a3\u4e48\u5feb\u3002\u8fc7\u51e0\u5e74\u518d\u95ee\u6211\u5427\u3002", "Not again. Not so soon. Ask me in a few years."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u4f1a\u4e70\u6211\u4eba\u6c11\u7684\u9c9c\u8840\u5417\uff1f\u6eda\u51fa\u6211\u7684\u89c6\u7ebf\u3002", "You'd buy the blood of my people? Get out of my sight."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u3002\u547d\u540d\u738b\u56fd\u3002\u800c\u4e14\u4ee3\u4ef7\u6700\u597d\u662f\u503c\u5f97\u8840\u7684\u3002", ". Name the realm. And the price had better be worth the blood."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u6d88\u5931\u4e86\u3002\u518d\u4e5f\u6ca1\u6709\u4eba\u8bb2\u8fd9\u6837\u7684\u7b11\u8bdd\u4e86\u3002", " is gone. Nobody tells jokes like that anymore."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u51e0\u4e4e\u5149\u79c3\u79c3\u7684\u3002\u6ca1\u6709\u4ec0\u4e48\u53ef\u4ee5\u8282\u7701\u7684\u3002", " are nearly bare. Nothing to spare."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff08\u4f60\u5df2\u7ecf\u6709\u4e86 {0} \u5b88\u536b{1}\u3002\uff09", "Times are dangerous. I'll watch your back, for gold."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u63e1\u7d27\u4ed6\u4eec\u7684\u6b66\u5668*\u4f60\u96c7\u4f63\u4e86\u6700\u597d\u7684\u4eba\u3002", "*grips their weapon* You've hired the best."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u4f4e\u58f0\u7948\u7977*\u5728\u90a3\u91cc\u3002\u4f60\u73b0\u5728\u88ab\u76d1\u89c6\u4e86\u3002", "*murmurs a prayer* There. You're watched over now."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u73af\u987e\u56db\u5468*\u8d70\u3002\u8fc5\u901f\u5730\u3002\u518d\u4e5f\u4e0d\u4f1a\u4e86\u3002", "*glances around* Go. Quickly. And never again."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u60f3\u6536\u4e70\u6211\u5417\uff1f\u8fd9\u53c8\u662f\u53e6\u5916\u4e00\u9879\u6536\u8d39\u4e86\u3002", "You'd try to buy me? That's another charge."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u79bb\u5f00\u4f60\uff1a\u4f60\u4eec\u7684\u738b\u56fd\u6b63\u5904\u4e8e\u6218\u4e89\u4e4b\u4e2d\u3002", " leaves you: your realms are at war."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("   \u00b7{num7:F0} \u74f7\u7816\u8fdc\u79bb", "   \u00b7   {num7:F0} tiles away"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u5bf9\u738b\u5ba4\u7684\u503a\u52a1\u5df2\u7ecf\u6e05\u507f\u3002\u522b\u8ba9\u6211\u540e\u6094\u3002", "Your debt to the crown is settled. Don't make me regret it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65e0\u6cd5\u63a5\u7ba1\u968f\u673a\u8df3\u8dc3\uff0c\u60a8\u7684\u89c6\u56fe\u53ef\u80fd\u4f1a\u53cd\u5f39", "could not take over the random hops, your view may bounce"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u6bd4\u4f60\u5f3a\u3002\u5e26\u4e0a\u670b\u53cb\uff0c\u6216\u8005\u66f4\u597d\u7684\u6b66\u5668\u3002", " is stronger than you. Bring friends, or a better weapon."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5411\u4ed6\u4eec\u5ba3\u8bb2\u6709\u4e9b\u4eba\u4f1a\u542c\uff0c\u6709\u4e9b\u4eba\u4e0d\u4f1a\u3002", " and preach to them. Some will listen, some won't."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7b49\u7b49\u3002\u5728\u6211\u4eec\u52a8\u6447\u4e4b\u524d\uff0c\u8ba9\u6211\u518d\u8bf4\u4e00\u904d\u3002", "Wait. Before we shake on it, let me say it back."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5728\u57ce\u9547\u8fb9\u7f18\u7684\u7530\u91ce\u91cc\u3002\u6210\u719f\u65f6\u7528\u624b\u91c7\u96c6\u3002", "In the fields at the edge of town. Gather it by hand when it's ripe."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5fae\u7b11\uff1f\u4f60\u613f\u610f\u544a\u8bc9\u4ed6\u4eec\u5173\u4e8e\u6211\u7684\u4e8b\u5417\uff1f", " smiles? Would you tell them about me?"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8ddf\u6211\u4e00\u8d77\u53bb\u90a3\u91cc\u5417\uff1f\u6211\u4f1a\u8ddf\u968f\u4f60\u7684\u5f15\u5bfc\u3002", "Walk with me there? I'll follow your lead."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5411\u6c11\u4f17\u4f20\u9053\uff0c\u4e3a{1}\u8d62\u5f97{0}\u7075\u9b42\u3002", "Preach to the people, win {q.Need} souls for {q.Thing}."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u628a\u5b83\u4ea4\u5230\u4ed6\u4eec\u624b\u4e2d*\u5e72\u5f97\u597d\u3002\u8c22\u8c22\u4f60\uff01", "*turns it over in their hands* Fine work. Thank you!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff01\u6211\u4f1a\u628a\u6211\u7684\u94b1\u5305\u653e\u5f97\u66f4\u8fd1\u4e00\u4e9b\u3002\u8c22\u8c22\u3002", "! I'll keep my purse closer. Thank you."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u4eec\u7684\u8d22\u52a1\u4e3b\u7ba1\u8fd8\u5728\u6e05\u70b9\u6700\u540e\u4e00\u4efd\u793c\u7269\u3002", "Your treasurers are still counting the last gift."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u4eba\u5934\u8981\u51fa\u4ef7\u3002\u6211\u4eec\u4e0d\u6b66\u88c5\u4e0d\u6cd5\u4e4b\u5f92\u3002", "There's a price on your head. We don't arm outlaws."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u53ea\u6709\u7537\u4eba\u643a\u5e26\u6b66\u5668\u3002\u8fd9\u662f\u6211\u4eec\u7684\u65b9\u5f0f\u3002", " only the men bear arms. It's our way."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u53ea\u6709\u5973\u6027\u643a\u5e26\u6b66\u5668\u3002\u8fd9\u662f\u6211\u4eec\u7684\u65b9\u5f0f\u3002", " only the women bear arms. It's our way."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8bbe\u7f6e\u5347\u7ea7\uff1a\u89c6\u91ce\u548c\u773c\u9ad8\u91cd\u7f6e\u4e3a\u65b0\u7684\u9ed8\u8ba4\u503c", "settings upgraded: field of view and eye height reset to the new defaults"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7269\u4f53\u4fdd\u7559\u4e09\u7ef4\u7ec6\u8282\u7684\u8ddd\u79bb\uff0c\u8fdc\u5904\u8f6c\u4e3a\u50cf\u7d20", "How far things stay 3D before turning to pixels"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u751f\u7269\u4fdd\u6301\u4e09\u7ef4\u6a21\u578b\u7684\u8ddd\u79bb\uff0c\u8fdc\u5904\u8f6c\u4e3a\u8272\u70b9", "How far creatures stay 3D, not specks"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u51cf\u5c11\u8f6c\u52a8\u65f6\u7684\u753b\u9762\u6495\u88c2\uff1b\u5173\u95ed\u53ef\u63d0\u9ad8\u5e27\u7387", "No tearing as you turn; off for a few more frames"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u795e\u89c2\uff1a\u571f\u5730\u5237\u65b0\u5931\u8d25\uff08\u8fdb\u884c\u4e0b\u4e00\u5e27\uff09\uff1a ", "god view: land refresh failed (it carries on next frame): "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" {magnitude:F1} \u74f7\u7816", " ({magnitude:F1} tiles)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("Worldfall \u80cc\u666f\u97f3\u4e50\uff1a\u5f00 ", "Worldfall music: on "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6cbb\u6108\u761f\u75ab\u548c\u6bd2\u836f\u5e76\u6cbb\u6108\u4f60\u5468\u56f4\u7684\u6bcf\u4e2a\u4eba", "Cure plague and poison and heal everyone around you"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6218\u4e89\u5450\u558a\uff1a\u6124\u6012\u5145\u6ee1\u4f60\uff0c\u4f60\u7684\u654c\u4eba\u52a8\u6447", "A war cry: rage fills you and your foes falter"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u53ec\u96c6\u72fc\u7fa4\uff1a\u4f60\u9644\u8fd1\u7684\u540c\u7c7b\u52a0\u5165\u4f60\u7684\u72e9\u730e", "Call the pack: your kind nearby join your hunt"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u4f60\u7684\u5b50\u6c11\u632f\u4f5c\u8d77\u6765\uff0c\u4e0e\u4f60\u4e00\u8d77\u51b2\u950b\uff01", " of your people take heart and charge with you!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u4ea4\u53c9\u53cc\u81c2*\u6211\u4e0d\u76f8\u4fe1\u4f60\u3002\u4e0d\u5728\u8fd9\u91cc\u3002", "*crosses arms* I don't trust you. Not here."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u51c6\u5907\u597d\u5c06\u4e00\u4e2a\u65b0\u4eba\u5e26\u5230\u8fd9\u4e2a\u4e16\u754c\u4e0a\u3002", "I'm ready to bring a new one into the world."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ec0\u4e48\u4e5f\u6ca1\u53d1\u751f\u3002\u4e5f\u8bb8\u4f60\u8fd8\u6ca1\u6709\u51c6\u5907\u597d\u3002", "Nothing happened. Perhaps you're not ready."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u6447\u5934*\u8fd8\u6709\u4ec0\u4e48\u4e1c\u897f\u628a\u4f60\u56f0\u5728\u8fd9\u91cc\u3002", "*shakes head* Something holds you here yet."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u7684\u817f\u5df2\u7ecf\u4e0d\u4e00\u6837\u4e86\uff0c\u4f46\u6211\u8fd8\u8fc7\u5f97\u53bb\u3002", "My leg's not what it was, but I get by."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u95ea\u95ea\u53d1\u5149\u7684\u91d1\u7259*\u503c\u5f97\u6bcf\u4e00\u679a\u786c\u5e01\u3002", "*flashes a gold tooth* Worth every coin."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u751f\u6d3b\u662f\u7f8e\u597d\u7684\u3002\u6211\u4e0d\u4f1a\u6539\u53d8\u4efb\u4f55\u4e8b\u60c5\u3002", "Life is good. I wouldn't change a thing."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u90a3\u5c31\u8d70\u5427\u3002\u7ed3\u675f\u540e\u4e0d\u8981\u6307\u671b\u53d7\u5230\u6b22\u8fce\u3002", "Then go. And don't expect a welcome when it's over."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" {0} \u5b9a\u5c45\u8005{1} \u4e0e\u4f60\u540c\u5728\u3002", " {0} settler{1} with you."));
