        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4e3a {2} \u8d2d\u4e70\u4e86 {0} {1}", "Bought {5} {Work.ResourceName(res)} for {Gold(price)}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u628a\u624b\u653e\u5728\u989d\u5934\u4e0a*\u63a5\u53d7\u4f17\u795e\u7684\u9752\u7750\u3002", "*lays a hand on your brow* Go with the gods' favour."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f88\u516c\u5e73\u3002\u5982\u679c\u4f60\u9700\u8981\u6211\u5c31\u6253\u7535\u8bdd\u7ed9\u6211\u3002", "Fair enough. Call me if you need me."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u89d2\u8272\u9009\u9879\u5361\uff1a\u65e0\u6cd5\u8bfb\u53d6\u7269\u54c1\u548c\u7279\u5f81\uff1a ", "character tab: could not read the items and traits: "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7535\u8def\u677f\u662f\u88f8\u9732\u7684\u3002\u548c\u5e73\u65f6\u671f\u2026\u2026\u6682\u65f6\u3002", "The board is bare. Peaceful times... for now."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u6240\u6709\u88ab\u6807\u8bb0\u7684\u6218\u58eb\u90fd\u65e0\u6cd5\u5230\u8fbe\u65d7\u5e1c ", "None of your marked warriors can reach flag "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u6ca1\u6709\u8239\u53ea\u3002\u6709\u7801\u5934\u7684\u57ce\u9547\u5efa\u9020\u5b83\u4eec\u3002", "No ships of yours. Towns with docks build them."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65e0\u6cd5\u63a5\u7ba1\u8fd0\u52a8\u68c0\u67e5\uff0c\u8dd1\u6b65\u53ef\u80fd\u4f1a\u963b\u6b62\u4f60", "could not take over the movement check, running may stop you"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4e0e\u4ed6\u4eec\u9762\u5bf9\u9762\u4ea4\u8c08\uff0c\u7136\u540e\u56de\u5230\u6211\u8eab\u8fb9 ", ", speak to them face to face, then come back to me, "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u8be2\u95ee\u90a3\u91cc\u7684\u4efb\u4f55\u4eba\uff1b\u4eba\u4eec\u4e92\u76f8\u8ba4\u8bc6\u3002", " Ask anyone there; folk know each other."));
