        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u6162\u6162\u5730\u70b9\u5934*\u73b0\u5728\u8bf4\u6bd4\u4ee5\u540e\u8bf4\u66f4\u597d\u3002", "*nods slowly* Better to say so now than later."));
