        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u5df2\u7ecf\u670d\u52a1\u4e86\u3002\u542c\u4ece\u4f60\u7684\u547d\u4ee4\uff08M\uff09\u3002", "You already serve. Look to your orders (M)."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5f88\u5e73\u9759\u3002\u5728\u8bad\u7ec3\u5047\u4eba\u4e0a\u94bb\u5b54\u5e76\u4fdd\u6301 ", " is at peace. Drill at the training dummy and keep "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u60a8\u7684\u5730\u56fe\uff08M\uff09\u663e\u793a\u6700\u8fd1\u7684\u7a7a\u5730\uff0c ", " Your map (M) shows the nearest free land, "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5bf9\u8bdd\u4e2d\uff1a\u9009\u62e9\u5e76\u786e\u8ba4\uff08Esc \u79bb\u5f00\uff09", "In a talk: choose, say it (Esc leaves)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7ad9\u5b9a\u65f6\u67e5\u770b\u5bb6\u5ead\u5730\u56fe\uff08\u4efb\u4f55\u8eab\u4efd\u5747\u53ef\uff09", "Your family's map, whoever you are (standing still)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4fef\u89c6\u89c6\u89d2\uff1b\u5728\u5730\u56fe\u4e2d\u5207\u6362\u4e09\u7ef4\u4e16\u754c\u89c6\u56fe", "Top-down view; on the map, the 3D world"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8c03\u6574\u89c6\u70b9\u9ad8\u5ea6\uff08PgUp\u3001PgDn\uff09", "Raise or lower the eye (PgUp, PgDn)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5faa\u73af\u663c\u591c\uff0c\u6216\u56fa\u5b9a\u5728\u67d0\u4e2a\u65f6\u523b\uff08F7\uff09", "Let the days pass, or keep one hour (F7)"));
