        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6e38\u620f\u65c1\u7ed8\u56fe\u5931\u8d25\uff08\u540c\u6b65\u7ed8\u56fe\u51e0\u79d2\uff09\uff1a ", "drawing beside the game failed (drawing in step for a few seconds): "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("LMB:\u5de6\u722a\u6fc0\u5149|RMB:\u53f3\u722a\u6fc0\u5149", "LMB:Left claw laser|RMB:Right claw laser"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u58eb\u5175\uff08{num}\uff09\u8fdb\u519b\u4fdd\u536b\u5b83\u3002", "Your soldiers ({num}) march to defend it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u4f60\u7684\u57ce\u9547\u73b0\u5728\u662f\u4ed6\u4eec\u7684\u4e86\uff0c\u4f60\u4e5f\u662f\u3002", " Your town is theirs now, and so are you."));
