        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u952e\u4f4d\u8bf4\u660e\u5df2\u663e\u793a\uff08\u518d\u6309 ? \u5173\u95ed\uff09", "Controls shown (press ? again to close)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6309\u4f4fX\u7784\u51c6\uff0c\u677e\u5f00\u5219\u6295\u63b7\u70b9\u71c3\u7684\u70b8\u5f39", "Hold X to aim, let go to throw a lit bomb"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5728\u4f60\u7784\u51c6\u7684\u5730\u65b9\u53ec\u5524\u9ab7\u9ac5\uff0c\u4e3a\u4f60\u800c\u6218", "Call up skeletons where you aim, to fight for you"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6309\u4f4fX\u7784\u51c6\uff0c\u677e\u5f00\u5219\u6295\u63b7\u7206\u88c2\u7684\u706b\u7403", "Hold X to aim, let go to hurl a bursting ball of fire"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u91cd\u51fb\u5730\u9762\uff1a\u5468\u56f4\u7684\u654c\u4eba\u88ab\u51fb\u9000\u5e76\u6655\u7729", "Strike the ground: foes around you are thrown back and stunned"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u5df2\u7ecf\u62e5\u6709\u4e86\u6240\u6709\u4f60\u80fd\u62e5\u6709\u7684\u5b69\u5b50\u3002", "You already have all the children you can."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u70b9\u5934*\u5f00\u59cb\u4e86\u3002\u8fd9\u9700\u8981\u4e00\u6bb5\u65f6\u95f4\u3002", "*nods* It has begun. It will take a while."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff0c\u901a\u5f80\u7530\u91ce\u7684\u8def\u662f\u6ce5\u6cde\u7684\u3002\u94fa\u57ab\u5417\uff1f", ", the road to the fields is mud. Pave it?"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u5fae\u7b11\u6709\u70b9\u592a\u957f\u4e86*\u4eba\u4eec\u592a\u6709\u8da3\u4e86\u3002", "*smiles a little too long* People are so interesting."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5982\u679c\u6211\u53ef\u80fd\u4f1a\u51fa\u9519\uff0c\u90a3\u5c31\u4e00\u5b9a\u4f1a\u7684\u3002", "If it can go wrong for me, it will."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u66fe\u7ecf\u7275\u8fc7\u4e00\u5934\u725b\u3002\u5728\u6bcf\u4e2a\u80a9\u8180\u4e0a\u3002", "I once carried a cow. On each shoulder."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4e00\u76f4\u5728\u601d\u8003\u661f\u661f\u662f\u5982\u4f55\u79fb\u52a8\u7684\u2026\u2026", "I've been thinking about how the stars move..."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5475\u5475\u3002\u4f60\u4f1a\u5bf9\u6211\u6240\u505a\u7684\u4e8b\u611f\u5230\u60ca\u8bb6\u3002", "Heh. You'd be surprised what I've done."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u63e1\u4f4f\u4f60\u7684\u624b*\u662f\u7684\u3002\u4e00\u5343\u6b21\u662f\u7684\u3002", "*takes your hand* Yes. A thousand times yes."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f5c\u4e3a\u521b\u59cb\u4eba\u3002\u6211\u5c06\u5f00\u59cb\u4e00\u4e2a\u65b0\u6751\u5e84\u3002", "As a founder. I'll start a new village."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u770b\u5f97\u51fa\u6765\uff0c\u4f60\u7684\u5fc3\u8fd8\u6ca1\u6709\u51c6\u5907\u597d\u3002", "Your heart isn't ready, I can tell."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5bf9\u8c01\u5f00\u6218\uff1f\u5df2\u7ecf\u6ca1\u6709\u4eba\u53ef\u4ee5\u6218\u6597\u4e86\u3002", "War on whom? There's no one left to fight."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u7684\u751f\u6d3b\u4e00\u76f4\u5f88\u5e73\u9759\u3002\u6211\u559c\u6b22\u8fd9\u6837\u3002", "My life's been quiet. I like it that way."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u66fe\u7ecf\u7740\u706b\u8fc7\u4e00\u6b21\u3002\u4f24\u75a4\u4f9d\u7136\u5b58\u5728\u3002", "I was caught in a fire once. The scars stay."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ed6\u4eec\u4e0d\u4f1a\u4e0e\u8fd9\u91cc\u901a\u7f09\u7684\u4eba\u8fdb\u884c\u4ea4\u6613\u3002", "They won't trade with someone wanted here."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ee5 {2} \u51fa\u552e {0} {1}", "Sold {count} {Work.ResourceName(res)} for {Gold(n)}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u96c7\u4f63{0}\u62c5\u4efb\u62a4\u536b\uff0c\u671f\u9650{1}\u5e74", "Hire {0} as your guard for {1} year{2}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5e26\u8def\u3002\u5f53\u6211\u5728\u8eab\u8fb9\u65f6\uff0c\u6ca1\u6709\u4eba\u78b0\u4f60\u3002", "Lead the way. Nobody touches you while I'm around."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5230\u76ee\u524d\u4e3a\u6b62\u5f88\u5b89\u9759\u3002\u6211\u4e0d\u76f8\u4fe1\u5b89\u9759\u3002", "Quiet so far. I don't trust quiet."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8d3f\u8d42\u6211\uff1f\u4e3a\u4e86\u4ec0\u4e48\uff1f\u8fd9\u91cc\u4e0d\u9700\u8981\u4f60\u3002", "Bribe me? For what? You're not wanted here."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u8239\u53ea\u4e0d\u4f1a\u5411\u4f60\u81ea\u5df1\u7684\u57ce\u9547\u5f00\u706b\u3002", "Your ships won't fire on your own town."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u5e73\u5b89\u4e86\u3002\u5728\u7687\u5bb6\u8bae\u4f1a\uff08K\uff09\u5ba3\u6218\u3002", "You are at peace. Declare war in the royal council (K)."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6709\u4eba\u5df2\u7ecf\u4ece\u8fd9\u4e2a\u59d4\u5458\u4f1a\u83b7\u5f97\u4e86\u8d4f\u91d1\u3002", "Someone already took a bounty from this board."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65e0\u6cd5\u63a5\u7ba1\u8df3\u8dc3\uff0c\u8df3\u8dc3\u4fdd\u6301\u6e38\u620f\u7684\u9ad8\u5ea6", "could not take over jumping, jumps keep the game's heights"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u9700\u8981\u4e00\u628a\u9550\u6216\u4e00\u628a\u65a7\u5934\u6765\u5288\u77f3\u5934\u3002", "You'll need a pickaxe or an axe for the stone."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd9\u662f\u4e00\u6761\u6f2b\u957f\u7684\u8def\u3002\u968f\u8eab\u643a\u5e26\u98df\u7269\u3002", "It's a long road. Take food with you."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5c71\u4e0a\u7684\u5ca9\u77f3\u3002\u7528\u9550\u6216\u65a7\u5934\u6253\u7834\u5b83\u4eec\u3002", "Rocks in the hills. Break them with a pickaxe or an axe."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(", +{q.Renown} \u58f0\u671b", ", +{q.Renown} renown"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5728\u8fd9\u9644\u8fd1\u5f98\u5f8a\u3002\u5b83\u5413\u574f\u4e86\u5b69\u5b50\u4eec\u3002", " prowling near here. It frightens the children."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u80fd\u8f6c\u544a\u4ed6\u4eec\u5417\uff1f\u544a\u8bc9\u4ed6\u4eec\u6211\u5f88\u597d\u3002", "Would you carry word to them? Tell them I'm well."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u55ef\uff0c\u6211\u73b0\u5728\u4e0d\u80fd\u4ece\u4f60\u8fd9\u91cc\u593a\u8d70\u8fd9\u4e2a\u3002", "Hm, I can't take that from you right now."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5f00\u59cb\u2026\u2026\u544a\u8bc9\u6211\u4e00\u5207\u3002\u62ff\u7740\u8fd9\u4e2a\u3002", " began... tell me everything. And take this."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff1f\u771f\u7684\u5417\uff1f *\u8138\u7ea2*\u6211\u4e00\u76f4\u559c\u6b22 ", "? Really? *blushes* I've always liked "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff1f\u55ef\u3002\u4e0d\u662f\u6211\u559c\u6b22\u7684\u7c7b\u578b\u3002\u5bf9\u4e0d\u8d77\u3002", "? Hm. Not my type. Sorry."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u53ea\u6709\u56fd\u738b\u624d\u80fd\u53ec\u96c6\u7687\u5bb6\u8bae\u4f1a\u3002\u4f60\u662f ", "Only a king can call the royal council. You are "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u662f\u4f60\u7684\u76df\u53cb\u3002\u4f60\u4e0d\u80fd\u5411\u76df\u53cb\u5ba3\u6218\u3002", " is your ally. You cannot declare war on an ally."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5df2\u7ecf\u5815\u843d\u4e86\uff01\u4f60\u7684\u6218\u58eb\u51ef\u65cb\u5f52\u6765\u3002", " has fallen! Your warriors return in triumph."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u73b0\u5728\u8fd8\u4e0d\u662f\u53db\u4e71\u7684\u65f6\u5019\u3002\u518d\u8bd5\u4e00\u6b21\u3002", "The time isn't right for a rebellion. Try again."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u53ea\u6709\u4e00\u4e2a\u57ce\u9547\uff1a\u6ca1\u6709\u4eba\u53ef\u4ee5\u53cd\u6297\u3002", " has only one town: there is no one to rebel against."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u3002\u5b83\u7684\u9886\u5bfc\u8005\u5f00\u59cb\u503e\u542c......", ". Its leader begins to listen..."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u6218\u58eb\u4eec\u54cd\u5e94\u4f60\u7684\u53f7\u53ec\uff0c\u5e76\u80a9\u4f5c\u6218\u3002", " warriors answer your call and march to your side."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4e09\u679a\u51dd\u56fa\u6c7d\u6cb9\u5f39\u5728\u57ce\u9547\u4e2d\u6392\u6210\u4e00\u6392\u3002", "Three napalm bombs laid in a line across the town."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" {num} \u4f60\u5bb6\u548c\u4f60\u4e00\u8d77\u5b9a\u5c45\u3002", " {num} of your family settle there with you."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6325\u51fb\u3001\u547d\u4e2d\u3001\u5f13\u7bad\u3001\u98ce\u96e8\u7b49\u6a21\u7ec4\u97f3\u6548", "Your swings, hits, bow, wind and rain"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5730\u56fe\u4e0e\u751f\u7269\u7b2c\u4e00\u4eba\u79f0\u4e4b\u95f4\u7684\u955c\u5934\u8fc7\u6e21", "The swoop from the map into the eyes and back"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u53f3\u4e0a\u89d2\u663e\u793a\u751f\u7269\u5df2\u63a2\u7d22\u7684\u533a\u57df\uff08N\uff09", "Top right in first person, the land as your creature knows it (N)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u9644\u8fd1\u7684\u5df1\u65b9\u6218\u58eb\u4f1a\u653b\u51fb\u4f60\u6807\u8bb0\u7684\u654c\u4eba", "Your warriors near an enemy you ping go for it"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd8\u6ca1\u6709\u6700\u559c\u6b22\u7684\uff1a\u65e0\u8bba\u4f60\u770b\u8c01\uff0cB\u661f", "No favourites yet: B stars whoever you're looking at"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4e0a\u5e1d\u89c6\u56fe\u6846\u67b6\u5931\u8d25\uff08\u7a0d\u540e\u91cd\u8bd5\uff09\uff1a ", "god view frame failed (trying again shortly): "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5982\u679c\u786c\u5e01\u6b63\u786e\u7684\u8bdd\uff0c\u6211\u53ef\u4ee5\u6325\u5251\u3002", "For the right coin, I'll swing a sword."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ed3\u5e93\u69fd\u8df3\u8fc7\uff08\u5df2\u6709\u540c\u540d\u69fd\u4f4d\uff09: ", "Stash slot skipped (same-name slot exists): "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6309\u4f4fX\u7784\u51c6\uff0c\u677e\u5f00\u5219\u6254\u51fa\u4e09\u4e2a\u96ea\u7403", "Hold X to aim, let go to fling three snowballs"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6309\u4f4fX\u7784\u51c6\uff0c\u677e\u5f00\u5219\u53d1\u5c04\u7b49\u79bb\u5b50\u7bad", "Hold X to aim, let go to fire a bolt of plasma"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6309\u4f4fX\u7784\u51c6\uff0c\u677e\u5f00\u5219\u5410\u51fa\u4e00\u53e3\u9178\u6db2", "Hold X to aim, let go to spit a gob of acid"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6cbb\u6108\u5e76\u4fdd\u62a4\u4f60\u81ea\u5df1\u548c\u4f60\u5468\u56f4\u7684\u76df\u53cb", "Heal and shield yourself and your allies around you"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6cbb\u6108\u4f60\u81ea\u5df1\u548c\u4f60\u5468\u56f4\u7684\u6bcf\u4e00\u4e2a\u751f\u7269", "Heal yourself and every creature around you"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u4eba\u5934\u5728\u8fd9\u91cc\u51fa\u4ef7\u3002\u5148\u4ea4\u7f5a\u6b3e\u5427", "There's a price on your head here. Pay your fine first."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u611f\u89c9\u600e\u4e48\u6837\uff1f\u6211\u4eec\u7684\u5b9d\u5b9d\u6765\u4e86 ", "How are you feeling? Our baby comes "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u5598\u6c14*\u8fd9\u2026\u2026\u5f88\u6f02\u4eae\uff1f\u6211\u8ba4\u4e3a\uff1f", "*gasps* It's... beautiful? I think?"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u6328\u6253\u4e86\u3002\u6ee1\u57ce\u90fd\u662f\u4e00\u7638\u4e00\u62d0\u7684\u3002", " got a beating. Limping all over town."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4eca\u5e74\u4f60\u5df2\u7ecf\u542c\u8fc7\u6211\u7684\u8bdd\u4e86\u3002\u8c22\u8c22\u3002", ", you've already heard me this year. Thank you."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6bcf\u4e2a\u4eba\u90fd\u6765\u627e\u6211\u89e3\u51b3\u4ed6\u4eec\u7684\u95ee\u9898\u3002", "Everyone comes to me with their problems."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u770b\u5230\u5468\u56f4\u6709\u654c\u4eba\u5417\uff1f\u6211\u5f88\u60f3\u6253\u67b6\u3002", "Seen any enemies around? I'm itching for a fight."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65e9\u4e9b\u65f6\u5019\u53d1\u73b0\u4e86\u4e00\u5757\u95ea\u4eae\u7684\u5ca9\u77f3\u3002", "Found a shiny rock earlier."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u62cd\u62cd\u4f60\u7684\u80a9\u8180*\u4f60\u7684\u8170\u5e26\u4e0d\u9519\u3002", "*pats your shoulder* Nice belt you've got there."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u772f\u8d77\u773c\u775b*\u4f60\u4e0d\u662f\u6211\u4eec\u7684\u58eb\u5175\u3002", "*squints* You're no soldier of ours."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u7684\u7236\u6bcd\uff1f\u6211\u6839\u672c\u4e0d\u8bb0\u5f97\u4ed6\u4eec\u4e86\u3002", "My parents? I don't remember them at all."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u73b0\u5728\u9886\u5bfc\u3002\u522b\u8ba9\u6211\u540e\u6094\u544a\u8bc9\u4f60\u3002", "I lead it now. Don't make me regret telling you."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ed6\u4eec\u7684\u519b\u961f\u662f\u6211\u4eec\u7684\u4e09\u500d\u3002\u81ea\u6740\u3002", "Their army is three times ours. Suicide."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6ca1\u6709\u9ec4\u91d1\u53ef\u4ee5\u4ece\u6211\u8fd9\u91cc\u4e70\u5230\u6218\u4e89\u3002", "No gold buys a war from me."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u4e0d\u80fd\u7528\u627f\u8bfa\u6765\u652f\u4ed8\u6218\u4e89\u7684\u8d39\u7528\u3002", "You can't pay for a war with promises."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd9\u91cc\u51fa\u4ec0\u4e48\u4e8b\u60c5\u4e86\u5417\uff1f\u6211\u4eec\u4e4b\u95f4\u3002", "Is something going on here? Between us."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u964d\u4f4e\u58f0\u97f3*\u6211\u4eec\u4e2d\u7684\u4e00\u4e9b\u4eba\u662f ", "*lowers voice* Some of us are part of "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4eec\u73b0\u5728\u6ca1\u6709\u56fd\u738b\u3002\u5947\u602a\u7684\u65e5\u5b50\u3002", "We have no king right now. Strange days."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff1f\u628a\u6211\u4eec\u69a8\u5e72\uff0c\u5374\u6ca1\u6709\u4efb\u4f55\u56de\u62a5\u3002", "? Squeezes us dry and gives nothing back."));
