        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u773c\u775b\u7ea2\u4e86*\u539f\u8c05\u6211\u3002\u6211\u8f93\u4e86 ", "*eyes red* Forgive me. I lost "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7ed9\u4e88 {amount} \u91d1\u5e01", "Give {amount} gold"));
