        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5bf9\u4f60\u6765\u8bf4\uff0c\u4e00\u4e2a\u516c\u5e73\u7684\u4ef7\u683c\u3002", " For you, a fair price."));
