        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7ed9\u4ed6\u4eec\u4e00\u4e9b\u786c\u5e01\u6765\u6495\u6bc1\u4f60\u7684\u6d77\u62a5", "Slip them some coin to tear up your poster"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd9\u91cc\u7684\u571f\u5730\u4e0d\u4f1a\u5360\u636e\u4e00\u4e2a\u6751\u5e84\u3002", "The land won't take a village here."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u56fd\u738b\u7684\u5b50\u6c11\u8702\u62e5\u800c\u81f3\uff0c\u4fdd\u536b\u4ed6\uff01", "The king's people rush to defend him!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u4ece\u8fd9\u4e2a\u59d4\u5458\u4f1a\u83b7\u5f97\u4e86\u8d4f\u91d1\uff1a ", "You hold a bounty from this board: "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("Ping \u60a8\u6b63\u5728\u67e5\u627e\u7684\u4f4d\u7f6e\uff1a", "Ping where you're looking:"));
