        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("  \u00b7E \u5728\u7a7a\u5730\u4e0a\u00b7M\uff1a\u5730\u56fe", "  \u00b7  E on free land  \u00b7  M: map"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6ca1\u6709\u575a\u5b9e\u7684\u57fa\u7840\u53ef\u4ee5\u63d2\u4e0a\u65d7\u5e1c\u3002", "No solid ground to plant a flag."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u53f3\u952e\u5355\u51fb\uff08\u672a\u6807\u8bb0\uff09\uff1a\u53d6\u6d88\u5b83\u4eec", "Right-click (nothing marked): call them off"));
