        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u770b\u4e00\u773c\u4f60\u7684\u5305*\u4f60\u5df2\u7ecf\u6709\u4e86 ", "*glances at your bag* You've already got "));
