        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u90a3\u6211\u4eec\u5c31\u8fbe\u6210\u534f\u8bae\u4e86\u3002\u8c22\u8c22\u4f60\uff01", "Then we have a deal. Thank you!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(".\u4f60\u7684\u6307\u5357\u9488\u4f1a\u4e3a\u4f60\u6307\u660e\u65b9\u5411\u3002", ". Your compass will show the way."));
