        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u627e\u51fa\u662f\u8c01\u5e72\u7684\u3002\u6211\u4f1a\u5956\u52b1\u4f60\u7684\u3002", "Find who did it. I'll reward you."));
