        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u7ed3\u675f\u4e86\u3002\u4f60\u4eec\u7684\u6218\u58eb\u56de\u5bb6\u4e86\u3002", " is over. Your warriors come home."));
