        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5c48\u670d\u4e8e\u4f60\u7684\u529b\u91cf\u5e76\u4ed8\u51fa\u4ee3\u4ef7 ", " bows to your might and pays "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65b9\u5c16\u7891\u4e0d\u4f1a\u653b\u51fb\u4f60\u81ea\u5df1\u7684\u4eba\u6c11\u3002", "The obelisk will not strike your own people."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65b9\u5c16\u7891\u5c16\u53eb\u8d77\u6765\u3002\u5929\u4e4b\u6012\u964d\u4e34 ", "The obelisk screams. Heaven's wrath falls on "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7ed1\u7740\u70b8\u5f39\u7684\u8783\u87f9\u7528\u964d\u843d\u4f1e\u98de\u5411 ", "Crabs with bombs strapped to them parachute towards "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u6d88\u5931\u4e86\u3002\u4e0a\u9762\u7684\u98ce\u66b4\u6d88\u6563\u4e86\u3002", " is gone. The storm over it clears."));
