        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5b89\u5168\u3002\u6218\u4e89\u4f34\u968f\u7740\u547d\u4ee4\u800c\u6765\u3002", " safe. Orders come with war."));
