        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8d8a\u6e05\u6670\uff0c\u5e27\u7387\u5f00\u9500\u8d8a\u5927\uff08F5\uff09", "Sharper costs frames (F5)"));
