        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ece\u4f60\u7684\u4f4d\u7f6e\u5230\u5c0f\u5730\u56fe\u8fb9\u7f18\u7684\u683c\u6570", "Tiles from you to its rim"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7231\u4eba\u548c\u5b69\u5b50\u8ddf\u968f\u4f60\uff0c\u5e76\u968f\u4f60\u8fc1\u5c45", "Your lover and children walk with you and move town with you"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u8eba\u5728\u5e9f\u589f\u4e2d\u3002\u4f60\u7684\u8239\u4e0d\u5f00\u706b\u3002", " lies in ruins. Your ships hold their fire."));
