        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u62c9\u8fdb\u4f60\u7684\u58f3\u91cc\uff1a\u6682\u65f6\u770b\u5f00\u4e00\u773c", "Pull into your shell: blows glance off for a while"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u9884\u8ba1\uff0c\u5927\u7ea6{num2}\u4e2a\u6708", "Expecting, about {num2} months"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u4eec\u4e2d\u7684\u4e00\u4e2a\u4eba\u4e0d\u80fd\u751f\u5b69\u5b50\u3002", "One of you can't have children."));
