        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u8981\u79bb\u5f00\u6211\u4eec\u5417\uff1f\u5c31\u8fd9\u6837\u5417\uff1f", "You'd leave us? Just like that?"));
