        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u6253\u91cf\u4f60*\u5f88\u597d\u3002\u6709\u623f\u95f4\u5728 ", "*looks you over* Very well. There's room in "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6b22\u8fce\u3002\u7ed9\u81ea\u5df1\u627e\u4e00\u4e2a\u5c4b\u9876\uff1b ", "Welcome. Find yourself a roof; "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u56de\u5bb6\u3002\u542c\u8bf4\uff0c\u7761\u5f97\u5f88\u8f9b\u82e6\u3002", " home. Sleeping rough, I hear."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ece\u56fd\u5e93\u507f\u8fd8\u4ed6\u4eec\uff0815\u91d1\u5e01\uff09", "Pay them back from the treasury (15 gold)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff01\u5168\u9547\u7684\u4eba\u90fd\u4f1a\u542c\u5230\u8fd9\u4ef6\u4e8b\u3002", "! The whole town will hear of this."));
