        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u7684\u738b\u56fd\u9700\u8981\u6211\u3002\u5b83\u662f\u4ec0\u4e48\uff1f", "My kingdom needs me. What is it?"));
