        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u9700\u8981\u65b0\u5200\u7247\u5417\uff1f\u6211\u505a\u5230\u6700\u597d\u3002", "Need a new blade? I make the best."));
