        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8bf8\u795e\uff1f\u6211\u4ece\u6765\u6ca1\u6709\u89c1\u8fc7\u4e00\u4e2a\u3002", "Gods? I've never seen one."));
