        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u4e0d\u77e5\u9053\u662f\u4ec0\u4e48\u51fb\u4e2d\u4e86\u4ed6\u4eec\u3002", " won't know what hit them."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u6740\u4e86{num}\u3002\u5e76\u8ba1\u6570\u3002", "I've killed {num}. And counting."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5b89\u9759\u7684\u65f6\u5149\u3002\u613f\u4ed6\u4eec\u80fd\u957f\u4e45\u3002", "Quiet times. Long may they last."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u8c22\u5929\u8c22\u5730\uff0c\u4e00\u5207\u90fd\u5e73\u5b89\u4e86\u3002", " is at peace, thank the gods."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("{0}\u5df2\u7edf\u6cbb\u6211\u4eec{1}\u5e74\u3002", "{0} has ruled us {1} year{2}."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u53ea\u6709 {num} \u91d1\u5e01\u3002", "You have only {num} gold."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4eec\u81ea\u5df1\u7684\u751f\u6d3b\u8fd8\u52c9\u5f3a\u591f\u7528\u3002", "We've barely enough for ourselves."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4e0d\u884c\uff0c\u56e0\u4e3a\u4f60\u7684\u4eba\u5934\u8981\u51fa\u4ef7\u3002", "Not while there's a price on your head here."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd8\u6ca1\u6709\u4eba\u52a8\u8fc7\u4f60\u4e00\u6839\u624b\u6307\u5934\u3002", "Nobody's laid a finger on you yet."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7a7a\u7a7a\u7684\u53e3\u888b\u4e0d\u4f1a\u8d3f\u8d42\u4efb\u4f55\u4eba\u3002", "Empty pockets don't bribe anyone."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u55ef\u3002\u4f60\u7684\u8138\u4e00\u5b9a\u88ab\u98ce\u5439\u8d70\u4e86\u3002", "Hm. Your face must have blown away in the wind."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u6c14\u5598\u5401\u5401\u5730\u628a\u80a9\u8180\u8f6c\u5411\u4f60*", "*huffs and turns its shoulder to you*"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u6307\u5411\u4f60\uff0c\u7136\u540e\u6307\u5411\u5b83\u81ea\u5df1*", "*points at you, then at itself*"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u5305\u91cc\u6ca1\u6709\u4e1c\u897f\u5403\uff0c\u5e76\u4e14 ", "Nothing to eat in your bag, and "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u5df2\u7ecf\u6709\u4e86 {3} \u5b88\u536b\u3002", "You already have {3} guards."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u64a4\u9500\u4fdd\u62a4\uff1a\u4f60\u8fdd\u53cd\u4e86\u6cd5\u5f8b\u3002", " withdraws its protection: you broke its law."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u6709\u4e9b\u592a\u9065\u8fdc\u4e86\uff0c\u65e0\u6cd5\u5230\u8fbe\u3002", " Some are too far off to reach."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u91c7\u96c6\u6d46\u679c\u6216\u72e9\u730e\u6765\u5582\u517b\u5b83\u4eec\u3002", "Gather berries or hunt to feed them."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u65e0\u6cd5\u6ce8\u518c\u5bb6\u5ead\u7684\u4ee5\u4e0b\u4efb\u52a1\uff1a ", "could not register the family's follow tasks: "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd9\u4e0d\u4f1a\u53d1\u751f\u5728\u8fd9\u4e2a\u751f\u7269\u8eab\u4e0a\u3002", "That won't go on this creature."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u548c\u4f60\u5728\u4e00\u8d77\uff1a{1}\u7684{0}", "With you: {num} of {members.Count}"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4e16\u754c\u4e0a\u63a2\u7d22\u7684\u5730\u533a\u4e0d\u5230 1%", "Less than 1% of the world explored"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4e0d\u5728\u8fd9\u91cc\uff1a\u627e\u5230\u6982\u8ff0\u7684\u571f\u5730\u3002", "Not here: find outlined land."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd9\u91cc\u6ca1\u6709\u5bb6\u4eba\uff1a\u4f60\u4e00\u4e2a\u4eba\u53bb\u3002", "No family here: you go alone."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u6218\u58eb\u4eec\u8fdb\u519b\uff0c\u575a\u5b88\u65b0\u9635\u5730\u3002", " warriors march to hold the new ground."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u6807\u8bb0\u6218\u58eb\u90fd\u4e0d\u80fd\u53bb\u90a3\u91cc\u3002", "None of your marked warriors can go there."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u6807\u8bb0\u6218\u58eb\u90fd\u4e0d\u80fd\u53bb\u65d7\u5e1c ", "None of your marked warriors can go to flag "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u53f3\u952e\uff1a\u4f60\u6807\u8bb0\u7684\u8239\u53ea\u5411\u5979\u5f00\u706b", "Right-click: your marked ships fire on her"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u88ab\u6807\u8bb0\u7684\u6218\u58eb\u6765\u5230\u4f60\u8eab\u8fb9\u3002", " marked warriors come to your side."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("  \u00b7\u6307\u5357\u9488\u4e0a\u95ea\u70c1\u7684\u5927\u5934\u9488", "  \u00b7  the flashing pin on your compass"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f88\u597d\u7684\u6446\u8131\u3002\u8fd9\u662f\u4f60\u7684\u5956\u52b1\u3002", "Good riddance. Here's your reward."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u3002\u4ee5\u540e\u5bf9\u6211\u6765\u8bf4\u5c31\u6ca1\u5565\u7528\u4e86\u3002", ". After that it's no use to me."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u90a3\u5c31\u6447\u4e00\u6447\u5427\u3002\u5b8c\u6210\u540e\u56de\u6765\u3002", "Shake on it, then. Come back when it's done."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u3002\u624b\u5feb\u7684\u4eba\u3002\u4e0a\u6b21\u6211\u542c\u8bf4\uff0c ", ". Someone with quick hands. Last I heard, "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5df2\u7ecf\u6709\u4eba\u5728\u5e2e\u52a9\u6211\u4e86\uff0c\u8c22\u8c22\u3002", "Someone's already helping me, thank you."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u3002\u6211\u5df2\u7ecf\u597d\u4e45\u6ca1\u89c1\u5230\u4ed6\u4eec\u4e86\u3002", ". I haven't seen them in ages."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6b63\u662f\u6211\u4eec\u6240\u9700\u8981\u7684\u3002\u8c22\u8c22\u4f60\uff01", "Just what we needed. Thank you!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u6b7b\u4e86\uff1f\u6211\u4eec\u53c8\u53ef\u4ee5\u7761\u89c9\u4e86\uff01", " is dead? We can sleep again!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u66f4\u591a\u7684\u52c7\u58eb\u52a0\u5165\u8fdb\u519b\u884c\u5217 ", " more warriors join the march on "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u53ea\u80fd\u5bf9\u5bf9\u624b\u7684\u57ce\u9547\u8fd9\u4e48\u505a\u3002", "You can only do that to a rival's town."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u3002\u6709\u4e1c\u897f\u4ece\u4e0a\u9762\u6389\u4e0b\u6765...", ". Something falls from it..."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5728\u8fd9\u4e2a\u4e16\u754c\u63a5\u542c\u4f60\u7684\u53ec\u5524\u3002", " answer your call in this world."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u523a\u5ba2\u7684\u6bd2\u88ab\u53ca\u65f6\u53d1\u73b0\u3002 ", "Your assassin's poison is found in time. "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u4e0d\u591f\u4fe1\u4efb\u4f60\u3002\u5148\u9001\u793c\u7269\u5427\u3002", " doesn't trust you enough. Send gifts first."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5341\u51e0\u9897\u6d41\u661f\u76f8\u7ee7\u843d\u5728\u6751\u5e84\u4e0a\u3002", "A dozen meteors fall on the village, one after another."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4e00\u5ea7\u57ce\u9547\u79bb\u4f60\u7684\u5730\u76d8\u592a\u8fd1\u4e86\u3002", "A town has grown up too close to your site."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u98df\u7528\u80cc\u5305\u6216\u57ce\u5e02\u5e93\u5b58\u4e2d\u7684\u98df\u7269", "Eat from your bag or your city's stores"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5b8c\u6210\u4e00\u6b21\u663c\u591c\u5faa\u73af\u6240\u9700\u7684\u65f6\u95f4", "A whole day and night, while it cycles"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u63d0\u9ad8\u5e27\u7387\uff0c\u955c\u5934\u4ecd\u968f\u9f20\u6807\u8f6c\u52a8", "More frames; the view still follows the mouse"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u4e0b\u6765\uff1a\u5176\u5e26\u8fd8\u6709\u5176\u4ed6\u547d\u4ee4\u3002", " comes down: its band has other orders."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7528\u65a7\u5b50\u6216\u5f92\u624b\u780d|H:\u6536\u8d77\u6765", "Chop with an axe or bare hands|H:Put it away"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6846\u67b6\u5931\u8d25\uff0c\u7559\u4e0b\u7b2c\u4e00\u4eba\u79f0\uff1a ", "frame failed, leaving first person: "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5e73\u9762\u5730\u56fe\uff08V\u4ee3\u88683D\u4e16\u754c\uff09", "Flat map   (V for the 3D world)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("   \u00b7\u6eda\u52a8\u8fdb\u5165\u4ed6\u4eec\u7684\u773c\u775b", "   \u00b7   scroll in to step into their eyes"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u770b\u7740\u4e00\u4e2a\u751f\u7269\u5e76\u6309=\u6765\u63a5\u7ba1\u5b83", "Look at a creature and press = to take it over"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8bbe\u7f6e\u83dc\u5355\uff1a\u65e0\u6cd5\u8986\u76d6\u5730\u56fe\uff1a ", "settings menu: could not cover the map: "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6309\u4f4fX\u7784\u51c6\uff0c\u677e\u5f00\u5219\u6254\u77f3\u5934", "Hold X to aim, let go to throw a rock"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u54ac\u4f60\u9762\u524d\u7684\u751f\u7269\uff0c\u4f24\u53e3\u6108\u5408", "Bite the creature in front of you, healing from the wound"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u72b9\u8c6b*\u4eca\u5929\u4e0d\u884c\uff0c\u6211\u60f3\u3002", "*hesitates* Not today, I think."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u671f\u5f85\uff0c\u5927\u7ea6{num3}\u5e74", "Expecting, about {num3} years to go"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ece\u6b63\u5728\u4e0b\u6c89\u7684\u8239\u4e0a\u629b\u51fa\uff1a ", "thrown from a sinking boat: "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u5fae\u7b11*\u6211\u4e5f\u662f\u8fd9\u4e48\u60f3\u7684\u3002", "*smiles* I thought so."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u90a3\u5c31\u8d70\u5427\u3002\u4e0d\u8981\u5fd8\u8bb0\u6211\u4eec\u3002", "Then go well. Don't forget us."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u3002\u4f60\u73b0\u5728\u4e0d\u5c5e\u4e8e\u4efb\u4f55\u57ce\u9547\u3002", ". You belong to no town now."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5199\u4e86\u4e00\u672c\u4e66\uff01\u559c\u6b22\u90a3\u4e2a\u3002", " wrote a book! Fancy that."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ece\u7687\u5bb6\u5546\u5e97\u9001\u7cae\uff0830\u91d1\uff09", "Send grain from the royal stores (30 gold)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u55ef\uff1f\u6211\u4e0d\u8ba4\u8bc6\u4f60\uff0c\u65c5\u884c\u8005\u3002", "Hm? I don't know you, traveler."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u7684\u65f6\u95f4\u4e0d\u591a\u4e86\u3002\u8bf4\u5feb\u70b9\u3002", ", I have little time. Speak quickly."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4eec\u5f88\u5feb\u5c31\u8981\u76d6\u65b0\u623f\u5b50\u4e86\u3002", "We're putting up a new house soon."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u628a\u90a3\u628a\u9524\u5b50\u9012\u7ed9\u6211\uff0c\u597d\u5417\uff1f", "Hand me that hammer, would you?"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4eca\u5929\u522b\u903c\u6211\u3002\u6211\u662f\u8ba4\u771f\u7684\u3002", "Don't push me today. I mean it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u603b\u89c9\u5f97\u4e0a\u9762\u6709\u4eba\u559c\u6b22\u6211\u3002", "I've always felt someone up there likes me."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u3001\u4f60\u542c\u5230\u90a3\u58f0\u97f3\u4e86\u5417\uff1f\uff01", "D-did you hear that noise?!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u5f88\u53d7\u5ba0\u82e5\u60ca\uff0c\u4f46\u662f\u6ca1\u6709\u3002", "I am flattered, but no."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u3002\u53bb\u90a3\u91cc\uff0c\u5efa\u7acb\u4e00\u4e2a\u6751\u5e84 ", ". Go there, raise a village for "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u662f\u7684\u3002\u6211\u5df2\u7ecf\u7ed3\u675f\u6218\u6597\u4e86\u3002", "Yes. I'm done with fighting."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u4eec\u6c11\u65cf\u6709\u4ec0\u4e48\u98ce\u4fd7\u4e60\u60ef\uff1f", "What are your people's customs?"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u8fd8\u6ca1\u6709\u4eb2\u7231\u7684\uff0c\u8fd8\u6ca1\u6709\u3002", "No sweetheart for me, not yet."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f80\u4e8b\u5982\u6c34\u822c\u4ece\u6211\u8eab\u8fb9\u6e9c\u8d70\u3002", "The past slips away from me like water."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u6ca1\u53d1\u751f\u4ec0\u4e48\u5927\u4e8b\u3002\u7136\u800c\u3002", "Nothing much has happened to me. Yet."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u3002\u6ca1\u6709\u4ec0\u4e48\u6bd4\u5b83\u66f4\u597d\u7684\u4e86\u3002", ". Nothing beats it."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8bf4\u5b9e\u8bdd\uff1f\u73b0\u5728\u7684\u751f\u6d3b\u5f88\u597d\u3002", "Honestly? Life is good right now."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6e29\u6696\u7684\u623f\u5b50\u548c\u5b89\u9759\u7684\u591c\u665a\u3002", "A warm house and a quiet evening."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u2026\u2026\u4ed6\u4eec\u60f3\u8981\u6211\u4eec\u7684\u571f\u5730\u3002", "... they want our land."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u5c31\u662f\u738b\uff01\u60a8\u4e07\u5c81\uff0c\u965b\u4e0b\uff01", "You ARE the king! Long live you, majesty!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u6b7b\u4e86\uff0c\u5c4b\u5b50\u91cc\u5982\u6b64\u5b89\u9759\u3002", " died, the house is so quiet."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u54af\u54af\u7b11\u5e76\u6293\u4f4f\u4f60\u7684\u9f3b\u5b50*", "*giggles and grabs at your nose*"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7ed9\u6211\u7684\uff1f\u4f60\u4e0d\u5e94\u8be5\u8fd9\u6837\u505a\uff01", "For me? You shouldn't have!"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u91d1\u5e01\uff01\u6211\u6700\u559c\u6b22\u7684\u4e00\u53e5\u8bdd\u3002", "Coin! My favourite word."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ea4\u6613\uff1f\u5f53\u7136\uff0c\u8ba9\u6211\u4eec\u770b\u770b\u3002", "Trade? Sure, let's see."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u7ed9\u6211\u770b\u770b\u4f60\u7684\u6b66\u5668\u548c\u76d4\u7532\u3002", "Show me your arms and armor."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u7684\u5305\u6ee1\u4e86\u3002\u5148\u817e\u51fa\u7a7a\u95f4\u3002", "Your bag's full. Make room first."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u4eec\u7684\u536b\u5175\u4e0e\u4f60\u7ad9\u5728\u4e00\u8d77 ", "Our guards stand with you for "));
