        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u6ca1\u6709\u548c\u4efb\u4f55\u4eba\u5728\u4e00\u8d77\u3002", "I'm not with anyone."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f53\u6211\u4eec\u5931\u53bb\u5f88\u5c11\u7684\u65f6\u5019 ", "when we lost little "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f53\u4e00\u4e2a\u964c\u751f\u4eba\u5e2e\u52a9\u6211\u65f6 ", "when a stranger helped me with "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u6700\u53e4\u8001\u7684\u8bb0\u5fc6\u662f\u4ec0\u4e48\uff1f", "What's your oldest memory?"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4ece\u53d7\u4f24\u90a3\u5929\u8d77\u6211\u5c31\u8ddb\u4e86\u3002", "I limp since the day I was hurt."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8fd9\u4e9b\u70e7\u4f24\uff1f\u706b\u4e0d\u4f1a\u539f\u8c05\u3002", "These burns? Fire doesn't forgive."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u4f60\u77e5\u9053\uff0c\u6211\u5199\u4e86\u4e00\u672c\u4e66\u3002", "I wrote a book, you know."));
