        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u597d\u3002\u6211\u4eec\u4f1a\u60f3\u5ff5\u4f60\u7684\u3002", "Good. We'd miss you."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\n\u4f60\u4f1a\u653e\u5f03\u57ce\u4e3b\u4e4b\u4f4d ", "\nYou would give up the lead of "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u604b\u7231\u4e86\u3002\u90fd\u5199\u5b8c\u4e86 ", " is in love. It's written all over "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u6709\u4e86\u4e00\u4e2a\u65b0\u751f\u513f\u3002 ", " has a new baby. "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5be1\u5987\u517b\u8001\u91d1\uff0825\u91d1\uff09", "A pension for the widows (25 gold)"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u6df1\u6df1\u97a0\u8eac*\u8c22\u8c22\uff0c ", "*bows deeply* Thank you, "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u50f5\u786c\u5730\u97a0\u8eac*\u5f53\u7136\u3002", "*bows stiffly* Of course."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\uff01\u5929\u6c14\u771f\u597d\uff0c\u4e0d\u662f\u5417\uff1f", "! Lovely weather, isn't it?"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u53f9\u6c14*\u73b0\u5728\u4e0d\u884c\u2026\u2026", "*sighs* Not now..."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u522b\u6253\u6270\u6211\uff0c\u6211\u6ca1\u5fc3\u60c5\u3002", "Leave me alone, I'm not in the mood."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u54e6\uff0c\u55e8\u3002\u9700\u8981\u4e1c\u897f\u5417\uff1f", "Oh, hi. Need something?"));
