        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5de5\u4f5c\uff0c\u5de5\u4f5c\uff0c\u5de5\u4f5c\u2026\u2026", "Work, work, work..."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6709\u91d1\u5e01\u5417\uff1f\u6c42\u4e2a\u670b\u53cb\u3002", "Got any gold? Asking for a friend."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u522b\u518d\u76ef\u7740\u4e86\u3002\u6211\u77e5\u9053\u3002", "Stop staring. I know."));
