        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u5e76\u627e\u5230\u4e86\u4e00\u4e2a\u6751\u5e84 ", " and found a village for "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u90a3\u5c31\u522b\u8ba9\u6211\u7559\u4f4f\u4f60\u4e86\u3002", "Then don't let me keep you."));
