        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u6211\u7684\u5bb6\u4eba\u4e0d\u5173\u4f60\u7684\u4e8b\u3002", "My family is none of your business."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u8ddf\u6211\u8bf4\u8bf4\u4f60\u7684\u5bb6\u65cf\u5427\u3002", "Tell me about your clan."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u548c\u6211\u5728\u4e00\u8d77\u8fc7\u4e00\u6b21\u3002", " and I were together, once."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>(" \u73b0\u5728\u662f\u6211\u4eec\u7684\u9996\u9886\u4e86", " is our chief now."));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("*\u88c5\u8fdb\u91d1\u5b50*\u7684\u65d7\u5e1c ", "*pockets the gold* The banners of "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f53\u6211\u4eec\u5bb6\u91cc\u6709\u4eba\u53bb\u4e16\u65f6", "when we had a death in the family"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f53\u6211\u6700\u597d\u7684\u670b\u53cb\u53bb\u4e16\u65f6", "when my best friend died"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f53\u6211\u6765\u9886\u5bfc\u5c0f\u9547\u7684\u65f6\u5019", "when I came to lead the town"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f53\u6211\u4eec\u5360\u9886\u4e00\u5ea7\u57ce\u5e02\u65f6", "when we took a city"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f53\u6211\u4eec\u70e7\u6bc1\u4e00\u5ea7\u57ce\u5e02\u65f6", "when we burned a city"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f53\u6211\u4eec\u5931\u53bb\u4e00\u5ea7\u57ce\u5e02\u65f6", "when we lost a city"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f53\u6211\u611f\u53d7\u5230\u795e\u7684\u89e6\u6478\u65f6", "when I felt the touch of the gods"));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f53\u4e00\u4e2a\u964c\u751f\u4eba\u5e2e\u52a9\u6211\u65f6", "when a stranger helped me"));
