        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f53\u6211\u4eec\u7ed9\u5b69\u5b50\u53d6\u540d\u65f6 ", "when we named our child "));
        list.Add(new System.Collections.Generic.KeyValuePair<string, string>("\u5f53\u6211\u4eec\u6536\u517b\u4e00\u4e2a\u5b64\u513f\u65f6", "when we took in an orphan"));
